window.QUIZ=[{"id":"q001","t":"infarctus","q":"رجل ٥٨ سنة، مدخّن وعندو diabète (سكري)، إجا عالطوارئ بوجع صدر عاصر صرلو ٤٥ دقيقة، ممتد عالإيد الشمال، وما راح مع Trinitrine (نيترو). شو أقرب تشخيص؟","o":["Infarctus du myocarde (جلطة قلبية)","Angor stable (ذبحة مستقرّة)","Péricardite (التهاب التامور)"],"a":0,"x":"وجع أكتر من ٢٠ دقيقة وما بيروح بالراحة ولا بالـ Trinitrine = Infarctus. الـ Angor بيروح بأقل من ١٠ دقايق."},{"id":"q002","t":"infarctus","q":"نفس المريض: أي فحص دم هوّي الأهم والأدق لتأكيد الجلطة؟","o":["Troponine (تروبونين)","AST (إنزيم قديم)","LDH (إنزيم بيطلع متأخّر)"],"a":0,"x":"الـ Troponine هيي الأدق لأذية خلايا القلب، بتطلع بعد ٢–٤ ساعات وبتضلّ لـ ٧ أيام. AST نادراً بيستعمل."},{"id":"q003","t":"infarctus","q":"شو أهم علامة عالـ ECG بالـ STEMI؟","o":["Sous-décalage ST (نزول ST)","Sus-décalage ST (ارتفاع ST)","PR قصير + onde delta"],"a":1,"x":"ارتفاع الـ ST (sus-décalage) = STEMI. نزول الـ ST أكتر بالـ ischémie / Angor. الـ onde delta = WPW."},{"id":"q004","t":"infarctus","q":"الـ onde Q يلي بتظهر بعد الجلطة بتدلّ على:","o":["نقص تروية مؤقّت (ischémie) — بيرجع طبيعي","نسيج ميّت (nécrose) — تغيير دائم","التهاب بالتامور (péricardite) — مؤقّت"],"a":1,"x":"الـ onde Q = جلطة بكل سماكة الجدار، نسيج ميّت ما بيعطي كهربا، تغيير دائم. تغيّرات T و ST هيي المؤقّتة."},{"id":"q005","t":"infarctus","q":"مريضة إجت بعد ٤ أيام من وجع الصدر. أي مؤشّر بعدو مفيد ومرتفع عندها؟","o":["Myoglobine (ميوغلوبين)","LDH (أو التروبونين)","CK-MB (إنزيم القلب CK-MB)"],"a":1,"x":"الـ CK-MB بيرجع طبيعي بعد ٤٨ ساعة. الـ LDH ذروتو ٣–٤ أيام وبيضلّ لـ ١٠ أيام (والتروبونين لـ ٧ أيام) — لهيك مفيد للي بيجي متأخّر."},{"id":"q006","t":"infarctus","q":"بأول ساعة من MI، أي شي مش من العلاج الأولي؟","o":["Aspirine + O₂ إذا الـ saturation واطية","Digoxine دوز عالي","Morphine للوجع"],"a":1,"x":"العلاج الأولي: O₂، Aspirine، Héparine، Trinitrine، Morphine، وفتح الشريان (thrombolyse أو angioplastie). الـ Digoxine مش من علاج الجلطة الأولي."},{"id":"q007","t":"infarctus","q":"مريض جلطة بالمستشفى، أوّل شي بيعملو الممرّض لما يوصل:","o":["يبعتو يمشي بالممر","ينتظر نتيجة الدم قبل أي شي","ECG فوراً + monitoring + خط وريدي"],"a":2,"x":"بالـ MI: ECG بأقل من ١٠ دقايق، monitoring cardiaque، voie veineuse + prise de sang (troponine)، راحة بالتخت semi-Fowler."},{"id":"q008","t":"infarctus","q":"مريض عمرو ٧٥ وعندو سكري، تعبان ومعو ضيق نفس بلا وجع صدر، والـ troponine مرتفعة. شو هيدا؟","o":["Angor de Prinzmetal (ذبحة برينزمتال)","Myocardite أكيد","IDM silencieux (جلطة صامتة)"],"a":2,"x":"عند مرضى السكري والكبار، الجلطة ممكن تكون بلا وجع أو بوجع خفيف (IDM silencieux)."},{"id":"q009","t":"infarctus","q":"أي مضاعفة ما منراقبها كمضاعفة مباشرة للـ MI بالدرس؟","o":["Diabète insipide (السكري الكاذب)","Choc cardiogénique (صدمة قلبية)","Insuffisance cardiaque (قصور القلب)"],"a":0,"x":"مضاعفات الـ MI: arythmies، insuffisance cardiaque، choc cardiogénique. الـ diabète insipide مضاعفة الـ craniotomie."},{"id":"q010","t":"angor","q":"شاب ٥٠ سنة بيجيه وجع صدر لما يطلع الدرج وبيروح بعد ٥ دقايق راحة. الـ troponine طبيعية. شو عندو؟","o":["Angor stable (ذبحة مستقرّة)","Infarctus (جلطة قلبية)","Angor instable (ذبحة غير مستقرّة)"],"a":0,"x":"مع الجهد + بيروح بالراحة/Trinitrine بأقل من ١٠ دقايق + troponine طبيعية = Angor stable."},{"id":"q011","t":"angor","q":"مريضة بيجيها وجع صدر الصبح باكر وهيي نايمة بسبب spasme (تشنّج) بالشريان. هيدا:","o":["Angor stable (ذبحة مستقرّة)","Péricardite (التهاب التامور)","Angor de Prinzmetal (ذبحة برينزمتال)"],"a":2,"x":"Prinzmetal = تشنّج بالشريان، غالباً بالليل أو الصبح وهو بالراحة."},{"id":"q012","t":"angor","q":"ليش الـ Angor instable خطيرة؟","o":["لأنو ممكن تتحوّل لـ Infarctus","لأنو بتروح لحالها","لأنو دايماً بتعمل حرارة"],"a":0,"x":"بتجي حتى بالراحة، أقوى وأطول، وما بتروح منيح بالدوا ← ممكن تصير MI."},{"id":"q013","t":"angor","q":"شو بيعمل الـ Trinitrine تحت اللسان؟","o":["بيوسّع الشرايين وبيوقّف الوجع بسرعة","بيذوّب الجلطة بالشريان التاجي","بيبطّئ القلب وبيخفّف ضرباتو"],"a":0,"x":"الـ nitro بيوسّع الأوعية. الـ thrombolyse بتذوّب الجلطة، والـ bêta-bloquants بتبطّئ القلب."},{"id":"q014","t":"angor","q":"بنوبة Angor، الممرّض أعطى nitro والوجع بعدو موجود بعد ٢٠ دقيقة. شو لازم يفكّر؟","o":["طبيعي، منكمّل نطّر ومنعطيه nitro كمان","شك بـ Infarctus — ECG + troponine ونخبّر الطبيب","نعطيه أكل ونخلّيه يرتاح بالسرير"],"a":1,"x":"إذا الوجع طوّل أكتر من ١٥–٢٠ دقيقة وما راح بالـ nitro = شك بـ MI."},{"id":"q015","t":"angor","q":"الـ Test d'effort منعملو لـ:","o":["نقيس السكر بالدم بعد الأكل","نشوف الصمامات وحركة القلب بالإيكو","نشوف إذا الجهد بيطلّع الوجع وتغيّرات الـ ECG"],"a":2,"x":"المريض بيمشي على tapis مع ECG لنشوف إذا الجهد بيطلّع الـ ischémie."},{"id":"q016","t":"ecg","q":"الـ Onde P بتمثّل:","o":["انقباض البطينين (ventricules)","ارتخاء البطينين (repolarisation)","انقباض الأذينين (oreillettes)"],"a":2,"x":"P = أذينات، QRS = بطينات، T = ارتخاء/راحة البطينات (repolarisation)."},{"id":"q017","t":"ecg","q":"الـ PR الطبيعي:","o":["0.12 – 0.20 ثانية","أقل من 0.04 ثانية","أكتر من 0.30 ثانية"],"a":0,"x":"PR بين 0.12 و 0.20 ث = الوقت لتنتقل الإشارة من الأذينين للبطينين."},{"id":"q018","t":"ecg","q":"QRS الطبيعي لازم يكون:","o":["أكتر من 0.20 ث (أكتر من ٥ مربعات زغار)","أقل من 0.12 ث (أقل من ٣ مربعات زغار)","تماماً 0.40 ث (١٠ مربعات زغار)"],"a":1,"x":"QRS &lt; 0.12 ث. المربّع الزغير = 0.04 ث عسرعة 25 mm/s."},{"id":"q019","t":"ecg","q":"لاصقة RA (الإيد اليمين) لونها:","o":["أصفر","أحمر","أسود"],"a":1,"x":"RA أحمر، LA أصفر، LL أخضر، RL أسود — من الإيد اليمين مع عقارب الساعة."},{"id":"q020","t":"ecg","q":"لاصقة الإجر اليمين (RL) لونها:","o":["أسود (terre/أرضي)","أخضر (متل الزرع)","أحمر (متل الدم)"],"a":0,"x":"RL = أسود (الأرضي). LL = أخضر."},{"id":"q021","t":"ecg","q":"وين منحط V1؟","o":["4ème espace intercostal، شمال الـ sternum","5ème espace intercostal، خط نص الترقوة","4ème espace intercostal، يمين الـ sternum"],"a":2,"x":"V1 = الفراغ الرابع يمين القص، V2 = الرابع شمال القص، V4 = الخامس على خط نص الترقوة."},{"id":"q022","t":"ecg","q":"وين منحط V4؟","o":["بالنص بين V2 و V6 على الصدر، فوق القص مباشرة","تحت الإبط على الـ ligne axillaire moyenne","5ème espace intercostal على الـ ligne médio-claviculaire"],"a":2,"x":"V4 = الفراغ الخامس، خط نص الترقوة. V3 بالنص بين V2 و V4."},{"id":"q023","t":"ecg","q":"قبل الـ ECG، أي شي غلط؟","o":["يقعد ويحكي ويتحرّك عادي","يشلح الساعة والمعادن","ننظّف الجلد ونحلق إذا شعر كتير"],"a":0,"x":"لازم ينام على ضهرو (décubitus dorsal)، مرتاح، ما يحكي وما يتحرّك."},{"id":"q024","t":"ecg","q":"ورقة ECG عسرعة 25 mm/s، المربّع الزغير قديش؟","o":["0.20 ثانية","0.04 ثانية","1 ثانية"],"a":1,"x":"المربّع الزغير = 0.04 ث، والكبير (٥ زغار) = 0.20 ث."},{"id":"q025","t":"ecg","q":"بعد ما خلص الـ ECG لمريض عندو وجع صدر، أهم شي:","o":["نعطي النتيجة للطبيب دغري","نحطها بالملف ونفلّ","نعيدو بكرا"],"a":0,"x":"نكتب الاسم والتاريخ والساعة، ونعطي النتيجة للطبيب فوراً — خصوصاً مع وجع صدر."},{"id":"q026","t":"pericarde","q":"مريض بعد فيروس، عندو وجع صدر بيزيد لما ينام وبيخفّ لما يقعد ويميل لقدّام، وحرارة، وصوت احتكاك بالسماعة. شو عندو؟","o":["Péricardite (التهاب التامور)","Infarctus (جلطة قلبية)","Angor stable (ذبحة مستقرّة)"],"a":0,"x":"وجع الـ péricardite بيتغيّر مع الوضعية + frottement péricardique."},{"id":"q027","t":"pericarde","q":"أهم فحص لنشوف épanchement péricardique (مي حول القلب):","o":["EEG (تخطيط الدماغ)","Échographie cardiaque (إيكو)","Troponine (تروبونين)"],"a":1,"x":"الإيكو هيي الأهم للانصباب وللـ tamponnade."},{"id":"q028","t":"pericarde","q":"مريض بعد طعنة بالصدر: ضغط ٨٠/٥٠، أصوات القلب مكتومة، وعروق الرقبة منفوخة. شو هيدا؟","o":["Choc hémorragique بس (نزيف داخلي)","Tamponnade (Triade de Beck) (دكّ القلب)","Péricardite بسيطة (التهاب التامور)"],"a":1,"x":"Triade de Beck: hypotension + bruits du cœur assourdis + turgescence jugulaire (JVD) = Tamponnade."},{"id":"q029","t":"pericarde","q":"علاج الـ Tamponnade الفوري:","o":["Antibiotiques ٦ أسابيع بالوريد (مضادات حيوية)","Pacemaker (بطارية القلب) مؤقّت فوراً","Péricardiocentèse (إبرة تسحب المي من حول القلب)"],"a":2,"x":"الـ péricardiocentèse فوراً، وإذا رجعت المي ← fenêtre péricardique (جراحة)."},{"id":"q030","t":"pericarde","q":"مريض tamponnade، أي وضعية ومراقبة صح؟","o":["Semi-Fowler + signes vitaux كل ١٥ دقيقة","Trendelenburg (الراس لتحت) + vitals كل ٤ ساعات","ممدود مسطّح بلا مراقبة"],"a":0,"x":"Semi-Fowler (٣٠–٤٥°) ليتنفّس، vitals كل ١٥ دقيقة، O₂، خط وريدي، Foley + entrées/sorties، ومراقبة علامات الـ choc."},{"id":"q031","t":"endomyo","q":"مريض عندو صمام اصطناعي، صرلو أسبوعين حرارة، تعب، نفخة جديدة بالقلب، وحبوب بتوجّع عرؤوس أصابعو. شو أهم فحصين للتشخيص؟","o":["Radio thorax + ECG (صورة صدر + تخطيط)","Troponine + CK-MB (مؤشرات القلب)","Hémocultures (زرع دم) + ETO (إيكو عن طريق المري)"],"a":2,"x":"خطأ شائع! الـ Endocardite = Hémocultures (٣ عينات قبل الـ antibiotiques) + ETO لنشوف الـ végétations."},{"id":"q032","t":"endomyo","q":"الـ Nodules d'Osler هيي:","o":["بقع حمرا ما بتوجّع عراحة الإيد","حبوب زغار بتوجّع عرؤوس الأصابع","نفخة بالقلب"],"a":1,"x":"Osler = Ouch (بتوجّع). Janeway = بقع ما بتوجّع."},{"id":"q033","t":"endomyo","q":"إيمتى مناخد الـ hémocultures بالـ Endocardite؟","o":["قبل ما نبلّش الـ antibiotiques","بعد أسبوع antibiotiques","ما منحتاجها"],"a":0,"x":"قبل الدوا، مشان الجرثومة ما تختفي من العيّنة."},{"id":"q034","t":"endomyo","q":"أحسن فحص لنشوف الـ végétations (التنبّتات) عالصمامات:","o":["Radio thorax (صورة صدر بالأشعة)","ETO (échographie trans-œsophagienne) (إيكو عن طريق المري)","EEG (électroencéphalogramme) (تخطيط الدماغ)"],"a":1,"x":"الـ ETO هيي الأحسن للـ végétations. الـ Radio thorax ما بتبيّنهن."},{"id":"q035","t":"endomyo","q":"مدّة علاج الـ Endocardite بالـ antibiotiques IV:","o":["٤–٦ أسابيع","مدى الحياة","٣ أيام"],"a":0,"x":"علاج طويل ٤–٦ أسابيع بالوريد، وإذا الصمام تخرّب ← جراحة."},{"id":"q036","t":"endomyo","q":"شاب صرلو أسبوع رشح/grippe، هلق تعب كتير، خفقان، ضيق نفس، والـ troponine شوي مرتفعة، والإيكو: العضلة ضعيفة. أقرب تشخيص:","o":["Endocardite (التهاب بطانة القلب)","Angor stable (ذبحة مستقرّة)","Myocardite (التهاب عضلة القلب)"],"a":2,"x":"الـ myocardite غالباً فيروسية (Coxsackie) بعد رشح، والعضلة بتضعف."},{"id":"q037","t":"endomyo","q":"أهم نصيحة لمريض Myocardite:","o":["Repos (راحة) وممنوع جهد","يوقف الأكل","رياضة قوية ليقوّي القلب"],"a":0,"x":"الراحة أساسية — ممنوع رياضة/جهد — مع أدوية قصور القلب إذا لازم."},{"id":"q038","t":"endomyo","q":"بالـ Critères de Duke، التشخيص أكيد إذا في:","o":["٢ majeurs (رئيسيين)","١ mineur بس (ثانوي)","ولا شي (ولا معيار)"],"a":0,"x":"أكيد = ٢ majeurs، أو ١ majeur + ٣ mineurs، أو ٥ mineurs."},{"id":"q039","t":"endomyo","q":"شو ما بيزيد خطر الـ Endocardite؟","o":["Toxicomanie IV (مخدرات بالوريد)","Test d'effort (فحص الجهد)","شغل أسنان بلا حماية"],"a":1,"x":"العوامل: prothèse valvulaire، شغل أسنان، مخدرات بالوريد، cathéter طويل المدّة."},{"id":"q040","t":"pacemaker","q":"مريض نبضو ٣٨، دايخ وبيغمى عليه، والـ ECG: الإشارة ما بتوصل من الأذين للبطين. شو العلاج المناسب؟","o":["Pacemaker (BAV complet) (بطارية القلب)","Digoxine (ديجوكسين) لتقوية القلب","ICD (défibrillateur) (صادم مزروع)"],"a":0,"x":"BAV = حصار أذيني بطيني + bradycardie مع عوارض = Pacemaker. الـ Digoxine بتبطّئ أكتر."},{"id":"q041","t":"pacemaker","q":"بعد يومين من زرع pacemaker، المريض صار عندو ضيق نفس مفاجئ والـ SpO₂ نزلت. شو أكتر شي منشكّ فيه؟","o":["Infection بالجرح (التهاب مكان الجهاز)","Pneumothorax (هوا بالرية)","Diabète (سكري) — ارتفاع السكر"],"a":1,"x":"ضيق نفس مفاجئ + SpO₂ نازل بعد الزرع = Pneumothorax. الـ infection بتعطي حمرة وحرارة ووجع بالجرح."},{"id":"q042","t":"pacemaker","q":"شو الفرق بين الـ Pacemaker والـ ICD؟","o":["نفس الجهاز بس بأسامي مختلفة، التنين للقلب البطيء","ICD للقلب البطيء، والـ Pacemaker بيصدم القلب السريع","Pacemaker للقلب البطيء، ICD بيصدم القلب السريع الخطر"],"a":2,"x":"Pacemaker = يسرّع البطيء. ICD = يصدم السريع (TV/FV) ويمنع الموت المفاجئ."},{"id":"q043","t":"pacemaker","q":"بعد زرع pacemaker، أي تعليم غلط؟","o":["يخبّر قبل أي IRM","يرفع إيدو فوق راسو من تاني يوم","يحمل بطاقة الجهاز دايماً"],"a":1,"x":"ما يرفع الإيد من جهة الجهاز فوق الكتف ٤–٦ أسابيع — مشان السلك ما يتحرّك."},{"id":"q044","t":"pacemaker","q":"مريض pacemaker بدّو يحط التلفون:","o":["ما في فرق، وين ما بدّو يحطّو","بجيبة القميص فوق الجهاز مباشرة","بعيد عن الجهاز (متل الجيبة التانية)"],"a":2,"x":"يبعد عن المغناطيس والأجهزة القوية — ما يحطّ التلفون فوق الجهاز."},{"id":"q045","t":"pacemaker","q":"قديش لازم يعمل contrôle للـ pacemaker؟","o":["مرّة بالعمر","كل يوم","كل ٦ أشهر"],"a":2,"x":"مراجعة كل ٦ أشهر لفحص الجهاز والبطارية."},{"id":"q046","t":"pacemaker","q":"الـ Triple chambre / CRT لمين؟","o":["لمرضى Angor stable (ذبحة مستقرّة)","لمرضى insuffisance cardiaque (قصور القلب)","للأطفال بس (عيوب خلقية بالقلب)"],"a":1,"x":"الـ CRT بينظّم البطينين مع بعض عند مرضى قصور القلب."},{"id":"q047","t":"embolie","q":"مريض عندو FA (رجفان أذيني)، فجأة إجرو الشمال باردة، شاحبة، بلا نبض وبتوجّعو كتير. شو هيدا؟","o":["Varices (دوالي) بالإجر","TVP (thrombose veineuse) (جلطة الوريد)","Embolie artérielle (جلطة شريانية)"],"a":2,"x":"الـ 6P (douleur، pâleur، pouls absent، paresthésie، paralysie، froideur) = embolie artérielle. مصدرها غالباً القلب (FA)."},{"id":"q048","t":"embolie","q":"نفس المريض، شو منعمل بإجرو؟","o":["منخلّيها ممدودة أو نازلة شوي، بلا massage","منرفعها لفوق عمخدّة ومنحطّ تلج","منعملها massage لنحرّك الدم"],"a":0,"x":"خطأ شائع! بالـ embolie artérielle ما منرفع الإجر — الرفع بيقلّل الدم الشرياني. الرفع للـ TVP."},{"id":"q049","t":"embolie","q":"الـ antidote (الترياق) تبع الـ Héparine:","o":["Vitamine K (فيتامين ك)","Protamine (ترياق الهيبارين)","Naloxone (ترياق المورفين)"],"a":1,"x":"Protamine للـ héparine. Vitamine K للـ warfarine (anti-vitamine K)."},{"id":"q050","t":"embolie","q":"مريض على Héparine IV، شو منراقب؟","o":["النظر وحدقة العين","TCA + علامات النزيف","السكر بالدم بس"],"a":1,"x":"الـ héparine بتتراقب بالـ TCA (TCK)، ومنراقب النزيف."},{"id":"q051","t":"embolie","q":"عملية لشيل الجلطة من الشريان اسمها:","o":["Péricardiocentèse (بزل التامور)","Embolectomie (شيل الجلطة)","Laminectomie (عملية الديسك)"],"a":1,"x":"Embolectomie = شيل الـ embole (الجلطة)."},{"id":"q052","t":"embolie","q":"جلطة بالوريد بالإجر (TVP) أخطر شي فيها إنو:","o":["تعمل Angor (ذبحة) بالقلب","تطلع عالرية = embolie pulmonaire","تعمل حرارة والتهاب بالجلد"],"a":1,"x":"الجلطة الوريدية ممكن تطلع عالرية."},{"id":"q053","t":"choc","q":"مريض بعد MI: الضغط ٨٠/٥٠، البول ٢٠ ml/ساعة، جلدو بارد ورطب، نبض سريع ومشوّش. شو عندو؟","o":["Péricardite (التهاب التامور)","IC droite (قصور أيمن)","Choc cardiogénique (صدمة قلبية)"],"a":2,"x":"ضغط &lt; ٩٠ + بول &lt; ٣٠ ml/h + جلد بارد ورطب بعد MI = Choc cardiogénique."},{"id":"q054","t":"choc","q":"أهم سبب للـ Choc cardiogénique:","o":["Endocardite (التهاب بطانة القلب)","Pacemaker (بطارية القلب)","Infarctus du myocarde (جلطة قلبية)"],"a":2,"x":"أشهر سبب هوّي الـ MI، وكمان myocardite وقصور القلب."},{"id":"q055","t":"choc","q":"بالـ choc cardiogénique، الضغط الانقباضي عادةً:","o":["أكتر من ١٤٠","أقل من ٩٠ mmHg","طبيعي ١٢٠"],"a":1,"x":"Systolique &lt; 90 mmHg."},{"id":"q056","t":"choc","q":"أي دوا بيقوّي انقباض القلب بالـ choc؟","o":["Héparine (مميّع دم) (anticoagulant)","Furosémide (Lasix) بس (diurétique)","Dobutamine / Dopamine (inotropes) (مقوّيات القلب)"],"a":2,"x":"الـ inotropes (dopamine، dobutamine) بتقوّي انقباض القلب."},{"id":"q057","t":"choc","q":"الوضعية بالـ choc cardiogénique حسب الدرس:","o":["Trendelenburg (الراس لتحت)","على البطن","Semi-Fowler (نص جلوس)"],"a":2,"x":"بالـ PDF: وضعية نصف جلوس + O₂ + sonde urinaire + ميزان سوائل."},{"id":"q058","t":"ic","q":"مريضة عندها ورم بالإجرين، JVD (عروق رقبة منفوخة)، تضخّم كبد ومي بالبطن. الرية نضيفة. شو عندها؟","o":["IC gauche (قصور أيسر)","IC droite (قصور أيمن)","OAP (وذمة رئوية)"],"a":1,"x":"المي بالجسم (إجرين، كبد، رقبة، بطن) = IC droite. المي بالرية = IC gauche."},{"id":"q059","t":"ic","q":"مريض بيفيق بالليل بضيق نفس، عندو crépitants (خراخر) وسعلة. شو عندو؟","o":["IC gauche (قصور أيسر)","IC droite (قصور أيمن)","Péricardite (التهاب التامور)"],"a":0,"x":"المي بالرية: dyspnée، PND، crépitants، toux، ممكن OAP = IC gauche."},{"id":"q060","t":"ic","q":"قبل ما تعطي Digoxine، قست النبض لقيتو ٥٢. شو بتعمل؟","o":["بتعطي عادي وبتسجّل النبض","ما بتعطي ومنخبّر الحكيم","بتعطي دوز مضاعف لترفع النبض"],"a":1,"x":"خطأ شائع! النبض أقل من ٦٠ = ما منعطي الـ Digoxine ومنخبّر."},{"id":"q061","t":"ic","q":"مريض على Furosémide (Lasix)، شو أهم شي منراقبو بالدم؟","o":["السكر","الكالسيوم بس","البوتاسيوم (K)"],"a":2,"x":"الـ Lasix بيطلّع بوتاسيوم ← خطر hypokaliémie."},{"id":"q062","t":"ic","q":"أحسن طريقة نراقب فيها إذا المي عم تتجمّع بجسم مريض IC:","o":["نعمل EEG","نوزنو كل يوم","نقيس حرارتو"],"a":1,"x":"الوزن اليومي (نفس الساعة ونفس الميزان) + entrées/sorties."},{"id":"q063","t":"ic","q":"أي أكل منصح فيه مريض IC؟","o":["بس سكاكر وحلويات","كتير ملح وسوائل","قليل ملح + تحديد السوائل"],"a":2,"x":"غذاء قليل الصوديوم مع تحديد السوائل، وبلا كافيين."},{"id":"q064","t":"ic","q":"أي مضاعفة من الدرس بتجي من دوا IC نفسو؟","o":["Intoxication digitalique (تسمّم بالديجوكسين)","Méningite (التهاب السحايا) من الدوا","Hernie discale (ديسك) من الدوا"],"a":0,"x":"من مضاعفات القصور: تسمّم بالديجوكسين، نقص بوتاسيوم، OAP، choc."},{"id":"q065","t":"arythmies","q":"على الـ monitor: نبض سريع، منتظم، وQRS عريض (أكتر من ٣ مربعات). شو هيدا؟","o":["Tachycardie ventriculaire (تسرّع بطيني)","Tachycardie supraventriculaire (تسرّع فوق بطيني)","Rythme sinusal (إيقاع طبيعي)"],"a":0,"x":"خطأ شائع! QRS عريض = ventriculaire = خطير. QRS ضيّق = supraventriculaire."},{"id":"q066","t":"arythmies","q":"نبض ١٥٠، منتظم، وQRS ضيّق:","o":["Fibrillation ventriculaire (رجفان بطيني)","Tachycardie ventriculaire (تسرّع بطيني)","Tachycardie supraventriculaire (فوق بطيني)"],"a":2,"x":"QRS ضيّق (&lt; ٣ مربعات) = المنشأ فوق البطينين."},{"id":"q067","t":"arythmies","q":"على الـ ECG: PR أقل من 0.12 + onde delta. شو هيدا؟","o":["BAV (bloc auriculo-ventriculaire) (حصار أذيني بطيني)","FA (fibrillation auriculaire) (رجفان أذيني)","Wolff-Parkinson-White (WPW) (طريق كهربائي زيادة)"],"a":2,"x":"WPW = طريق كهربائي زيادة: PR قصير + موجة دلتا."},{"id":"q068","t":"arythmies","q":"أي شي مش من معايير الإيقاع الجيبي الطبيعي؟","o":["QRS أعرض من 0.12 ث","P قبل كل QRS","النبض بين ٦٠ و ١٠٠"],"a":0,"x":"الطبيعي: P قبل كل QRS، PR ثابت 0.12–0.20، شكل P ثابت، نبض ٦٠–١٠٠، ومسافات R-R متساوية."},{"id":"q069","t":"arythmies","q":"مريض عندو arythmie وصار دايخ وضغطو نزل. شو بتعمل؟","o":["بتنطّر لبكرا وبتعيد تقيس الضغط","بتخبّر الحكيم فوراً وبتتحضّر للإنعاش","بتعطيه مي وبتخلّيه يمشي شوي"],"a":1,"x":"أي arythmie مع دوخة، هبوط ضغط، وجع صدر أو إغماء = نخبّر فوراً ونجهّز للإنعاش."},{"id":"q070","t":"arythmies","q":"الكهربا الطبيعية للقلب بتطلع من:","o":["الأبهر (Aorte)","Nœud sinusal (SAN — العقدة الجيبية)","البطين الأيسر (Ventricule gauche)"],"a":1,"x":"الـ SAN هيي البطارية الطبيعية للقلب."},{"id":"q071","t":"chirurgie","q":"صمام ما بيسكّر منيح والدم بيرجع لورا، اسمو:","o":["Sténose (تضيّق) — الصمام ما بيفتح منيح","Insuffisance / régurgitation (قصور / ارتجاع)","Tamponnade (دكّ القلب) — مي حول القلب"],"a":1,"x":"Sténose = ما بيفتح منيح. Insuffisance = ما بيسكّر منيح والدم بيرجع."},{"id":"q072","t":"chirurgie","q":"مريض عمرو ٤٠ ركّب valve mécanique (صمام معدني). شو لازم طول عمرو؟","o":["ولا شي، بيعيش طبيعي بلا دوا","Antibiotique كل يوم طول عمرو","Anticoagulant (مميّع) + مراقبة INR"],"a":2,"x":"الصمام المعدني بيعيش طول العمر بس بدّو مميّع مدى الحياة + INR."},{"id":"q073","t":"chirurgie","q":"الـ valve biologique مناسبة أكتر لـ:","o":["الكبار بالعمر (لأنو ما بدّا مميّع مدى الحياة)","ما حدا (لأنها بتخرب بسرعة عند الكل)","الشباب الزغار (لأنها بتعيش أكتر من الميكانيكية)"],"a":0,"x":"بتعيش ١٠–١٥ سنة وما بدّا مميّع مدى الحياة — منيحة للكبار."},{"id":"q074","t":"chirurgie","q":"بالـ CABG، الـ greffon يلي من الإجر هوّي:","o":["Artère mammaire interne (شريان الصدر)","Artère radiale (شريان الإيد)","Veine saphène (وريد الإجر)"],"a":2,"x":"Veine saphène = وريد الإجر. الـ radiale من الإيد، والـ mammaire من الصدر."},{"id":"q075","t":"chirurgie","q":"بعد CABG، الـ drain thoracique نزّل ٣٠٠ ml دم بساعة. شو بتعمل؟","o":["طبيعي، منكمّل","منخبّر الحكيم دغري","منشلح الـ drain"],"a":1,"x":"نزيف كتير فجأة = طوارئ (خطر نزيف وtamponnade)."},{"id":"q076","t":"chirurgie","q":"بعد عملية القلب المفتوح، أي نصيحة غلط للبيت؟","o":["وقف التدخين نهائياً","ما يحمل أكتر من ٥ كغ لـ ٦ أسابيع","يسوق السيارة بعد ٣ أيام"],"a":2,"x":"السواقة بعد ٦ أسابيع، والنقاهة ٦ أسابيع."},{"id":"q077","t":"chirurgie","q":"قبل الـ CABG، شو منعلّم المريض؟","o":["TCDB (يسعل ويتنفّس عميق)","يوقف يتنفّس","ما يتحرّك أبداً بعد العملية"],"a":0,"x":"نعلّمو TCDB والتمارين، ونشرحلو الأنابيب والضمادات والـ O₂."},{"id":"q078","t":"examens","q":"مريضة بدّا تعمل IRM، وعندها pacemaker. شو بتعمل؟","o":["بتعطيها مهدّئ وبس وبتبعتها","بتبعتها عادي، الـ pacemaker ما بيأثّر","بتخبّر — الـ IRM ممنوع مع pacemaker أو clips معدنية"],"a":2,"x":"ممنوع IRM مع pacemaker أو clips/شظايا معدنية، ومنشيل كل المعادن."},{"id":"q079","t":"examens","q":"قبل الـ EEG، قديش منوقّف الأدوية والكافيين؟","o":["٨ ساعات","٢٤ ساعة","ساعتين"],"a":0,"x":"نوقّف الأدوية والكافيين ٨ ساعات قبل، ونطمّنو إنو ما في كهربا."},{"id":"q080","t":"examens","q":"قبل CT scan مع صبغة، أهم سؤال:","o":["إذا عندو حساسية على اليود والسمك/الأكل البحري والصبغة","إذا أكل فطور اليوم الصبح أو شرب قهوة","إذا بيحب الرياضة وبيمشي كل يوم"],"a":0,"x":"حساسية اليود/السمك/الصبغة، ونخبّرو عن حرقة الحلق واحمرار الوجه."},{"id":"q081","t":"examens","q":"مريض جايي لـ ponction lombaire، شو منفحص قبل؟","o":["TP و PTT (تخثّر) + NFS، ونوقّف المميّعات","السكر بالدم بس، وما منوقّف ولا دوا","ECG بس، والمميّعات منكمّلها عادي"],"a":0,"x":"من الصف: TP، PTT، NFS ونوقّف الـ anticoagulants لأن في خطر نزيف."},{"id":"q082","t":"examens","q":"الـ ponction lombaire منعملها بين:","o":["T1 و T2 (الفقرات الصدرية)","C1 و C2 (الفقرات الرقبية)","L3–L4 أو L4–L5"],"a":2,"x":"بين فقرات أسفل الضهر L3–L4 أو L4–L5 — تحت آخر النخاع الشوكي (L1–L2)."},{"id":"q083","t":"examens","q":"بعد الـ ponction lombaire، المريض بينام:","o":["ممدود على ضهرو مسطّح","قاعد عالكرسي","على جنبو والراس مرفوع"],"a":0,"x":"à plat (الكورس: ٢٤ ساعة) + يشرب مي كتير + نراقب مكان الإبرة."},{"id":"q084","t":"examens","q":"مريض عندو وجع راس قوي واستفراغ، والـ fond d'œil بيّن œdème papillaire. الحكيم طلب PL. شو المشكلة؟","o":["الـ HTIC ممنوع معها الـ PL — خطر انحشار الدماغ","لازم يعمل EEG أوّل قبل الـ PL — خطر نوبة","ما في مشكلة — الـ PL بيخفّف الضغط"],"a":0,"x":"خطأ شائع! œdème papillaire = HTIC، والـ HTIC contre-indication للـ PL."},{"id":"q085","t":"examens","q":"الـ œdème papillaire بالـ fond d'œil بيدلّ على:","o":["ضعف نظر عادي مع العمر","HTIC (ارتفاع الضغط داخل الجمجمة)","التهاب عين (conjonctivite)"],"a":1,"x":"خطأ شائع! الضغط جوّا الجمجمة عم يضغط على عصب العين."},{"id":"q086","t":"examens","q":"قبل الـ fond d'œil منعطي:","o":["Héparine (مميّع دم) وننبّه ما ينزف","نقط mydriatiques (موسّعة بؤبؤ) وننبّه إنو ما يسوق","Mannitol (مدرّ للوذمة) وننبّه يشرب مي"],"a":1,"x":"النقط بتوسّع البؤبؤ — النظر بيغبّش شوي، فما يسوق."},{"id":"q087","t":"examens","q":"مريض عندو canal carpien (نفق الرسغ). أي فحص بيقيس نشاط العضل والعصب؟","o":["EMG (تخطيط العضلات)","Fond d'œil (فحص قاع العين)","EEG (تخطيط الدماغ)"],"a":0,"x":"EMG = تخطيط العضلات. ومنشوف معه Na، K، Ca."},{"id":"q088","t":"examens","q":"بالـ EMG، شو منقول للمريض؟","o":["ممنوع يتحرّك أبداً وما رح يحسّ بشي طول الفحص","رح يحسّ بانزعاج بس مش وجع، ولازم يشدّ ويرخي العضل","رح ينام بالبنج العام طول الفحص"],"a":1,"x":"بالكورس: discomfort but not pain + flex and relax muscles."},{"id":"q089","t":"examens","q":"بعد angiographie cérébrale، أهم مراقبة:","o":["السكر بالدم كل ساعة وبس","النوم والراحة، ما في شي تاني نراقبو","مكان الإبرة (نزيف) + vitals + العلامات العصبية"],"a":2,"x":"After: VS، نهدّيه، نراقب مكان الإدخال للنزيف، والـ neurovital signs."},{"id":"q090","t":"examens","q":"عيّنات الـ LCR بعد الـ PL:","o":["منحطها بالبرّاد أسبوع وبعدين منبعتها","منخلّيها لبكرا الصبح عالطاولة","منكتب عليها منيح ومنبعتها فوراً عالمختبر"],"a":2,"x":"Label specimens properly and send to the lab immediately."},{"id":"q091","t":"examens","q":"قبل Blood chemistry (كيمياء الدم)، المريض لازم:","o":["يكون صايم (بلا أكل وشرب)","ياكل كتير قبل الفحص بساعة","ياخد Lasix (مدرّ) قبل الفحص"],"a":0,"x":"Withhold food and fluids before."},{"id":"q092","t":"examens","q":"شو الصرع (épilepsie) أكتر فحص بيتشخّص فيه حسب الصف؟","o":["Fond d'œil (فحص قاع العين)","EMG (تخطيط العضلات)","EEG (تخطيط الدماغ)"],"a":2,"x":"EEG ← épilepsie."},{"id":"q093","t":"evaluation","q":"الممرّض حكّ باطن إجر المريض، والإصبع الكبير طلع لفوق والأصابع فتحت. هيدا:","o":["Babinski positif — مشكلة بالجهاز العصبي المركزي","علامة HTIC أكيدة — لازم PL فوراً","طبيعي عند الكبير — ما بيعني شي"],"a":0,"x":"الطبيعي إنو الأصابع تنثني لتحت. Babinski + = مشكلة مركزية."},{"id":"q094","t":"evaluation","q":"مريض ما بيقدر يحكي أو يفهم الكلام بعد جلطة دماغية. هيدا اسمو:","o":["Aphasie (فقدان الكلام)","Diplopie (ازدواج رؤية)","Dysphagie (صعوبة بلع)"],"a":0,"x":"Aphasie = فقدان القدرة عالكلام. Dysphagie = صعوبة بلع. Diplopie = ازدواج رؤية."},{"id":"q095","t":"evaluation","q":"مريض بيشوف دوبل (صورتين). بالفرنسي/الإنكليزي:","o":["Diplopie (diplopia) (ازدواج رؤية)","Ptosis (ptôse) (تدلّي الجفن)","Tinnitus (acouphène) (طنين)"],"a":0,"x":"Diplopie = ازدواج الرؤية. Ptosis = تدلّي الجفن. Tinnitus = طنين."},{"id":"q096","t":"evaluation","q":"أي واحد من عوامل الخطر العصبية منقدر نغيّرو؟","o":["العمر (Âge)","قصة عائلية (Antécédents familiaux)","Hypertension (ارتفاع الضغط)"],"a":2,"x":"القابلة للتعديل: التعرّض لمواد كيماوية، سوء استعمال المواد، رياضات اصطدام، والضغط."},{"id":"q097","t":"evaluation","q":"مريض بعد AVC ما عاد بيقدر يلبس لحالو. التشخيص التمريضي:","o":["Hyperthermie (ارتفاع حرارة)","Excès de volume liquidien (زيادة سوائل)","Self-care deficit: dressing (عجز العناية الذاتية — اللبس)"],"a":2,"x":"من التشخيصات الفعلية: self-care deficit (feeding, bathing, dressing, toileting)."},{"id":"q098","t":"laminectomie","q":"بعد laminectomie، كيف منقلّب المريض؟","o":["ما منقلّبو أبداً","بيقعد لحالو ويلفّ ضهرو","Logrolling (كلّو قطعة وحدة)"],"a":2,"x":"Logrolling: الكتف والحوض سوا بلا ما يلوي الضهر، والمريض flat."},{"id":"q099","t":"laminectomie","q":"بعد laminectomie، الضماد صار عليه سائل شفاف. شو ممكن يكون؟","o":["عرق طبيعي من الحرارة — عادي","مي من الدوش — منغيّر الضماد وبس","LCR (سائل دماغي شوكي) — منخبّر"],"a":2,"x":"Inspect dressing for CSF and blood."},{"id":"q100","t":"laminectomie","q":"بعد laminectomie cervicale (بالرقبة)، شو ممنوع؟","o":["نقيس الضغط","نثني الرقبة","نعطي مسكّن"],"a":1,"x":"Prevent flexion of the neck after cervical laminectomy."},{"id":"q101","t":"laminectomie","q":"نصيحة للبيت بعد عملية الديسك:","o":["ينام على فرشة طرية كتير","ينام عجنبو والركبتين مطويين على فرشة قاسية","يحمل أغراض تقيلة ليقوّي ضهرو"],"a":1,"x":"Sleep on the side, hips and knees flexed, firm mattress، وما يحمل تقل."},{"id":"q102","t":"laminectomie","q":"أي مضاعفة من مضاعفات الـ laminectomie؟","o":["Angor (ذبحة)","Endocardite (التهاب بطانة القلب)","Rétention urinaire (احتباس البول)"],"a":2,"x":"مضاعفات: احتباس البول، نقص حركة وإحساس، infection، spasme، iléus paralytique."},{"id":"q103","t":"craniotomie","q":"بعد craniotomie، المريض صار يبوّل كتير ومميّع. شو بتشكّ فيه؟","o":["Diabète insipide (السكري الكاذب)","Infection urinaire (التهاب بولي)","IC droite (قصور القلب الأيمن)"],"a":0,"x":"العملية قريبة من الغدة النخامية (ADH) ← diabète insipide."},{"id":"q104","t":"craniotomie","q":"الوضعية بعد الـ craniotomie (supratentorielle) حسب الكورس:","o":["على البطن","Trendelenburg (الراس لتحت)","Semi-Fowler (نص جلوس)"],"a":2,"x":"Keep the patient in semi-Fowler's position."},{"id":"q105","t":"craniotomie","q":"قبل الـ craniotomie، شو من التحضير الخاص؟","o":["صيام ٣ أيام","حلاقة الراس","حلاقة الإجرين"],"a":1,"x":"Prepare the patient for preoperative shaving of the head."},{"id":"q106","t":"craniotomie","q":"أي واحدة من مضاعفات الـ craniotomie؟","o":["Angor stable (ذبحة مستقرّة) + Arythmie (اضطراب نبض)","Hernie discale (ديسك) + Sciatique (عرق النسا)","Méningite + HTIC + convulsions (التهاب سحايا + ضغط بالجمجمة + نوبات)"],"a":2,"x":"HTIC، convulsions، détresse respiratoire، diabète insipide، déficits، infection، méningite."},{"id":"q107","t":"avc","q":"مريض جلطة دماغية، الـ CT بيبيّن نزيف (AVC hémorragique). أي دوا ما منعطيه؟","o":["Héparine (مميّع)","Mannitol (مدرّ للوذمة)","Phénytoïne (ضد الصرع)"],"a":0,"x":"ما منعطي héparine إذا في نزيف — لهيك الـ CT ضروري قبل."},{"id":"q108","t":"avc","q":"شو الوضعية المنصوح فيها لمريض AVC حسب الكورس؟","o":["على البطن","Semi-Fowler (نص جلوس)","Trendelenburg (الراس لتحت)"],"a":1,"x":"Position: semi-Fowler's."},{"id":"q109","t":"avc","q":"مريض AVC بالتخت، قديش منقلّبو؟","o":["ما منقلّبو","كل ساعتين","مرة باليوم"],"a":1,"x":"Turn and position the patient every 2 hours + bas anti-embolie + soins de la peau."},{"id":"q110","t":"avc","q":"مريض عندو FA إجتو فجأة شلل بجهة وحدة وما عاد يحكي. أكتر سبب محتمل:","o":["Hernie discale (ديسك) ضغطت عالأعصاب","Embolie (جلطة طايرة من القلب) عالدماغ = AVC","Péricardite (التهاب التامور) مع حرارة"],"a":1,"x":"الـ FA بتعمل جلطات بالقلب ممكن تروح عالدماغ (AVC) أو عالإجر (embolie artérielle)."},{"id":"q111","t":"avc","q":"بالـ AVC، أي دوا لتخفيف وذمة الدماغ بالكورس؟","o":["Dexaméthasone (Décadron) / Mannitol (كورتيزون / مدرّ)","Digoxine (ديجوكسين) / Aténolol (bêtabloquant)","Trinitrine (نيترو) / Héparine (مميّع دم)"],"a":0,"x":"Glucocorticoid: dexamethasone + diurétique osmotique mannitol."},{"id":"q112","t":"avc","q":"الأكل لمريض AVC حسب الكورس:","o":["قليل ملح وزيادة بوتاسيوم","كتير ملح لحتى يرتفع الضغط","بس سوائل، بلا أكل نهائياً"],"a":0,"x":"Diet: low-sodium, increased potassium."},{"id":"q113","t":"htic","q":"مريض بعد ضربة عالراس: وجع راس قوي، استفراغ بالقوة، وغباش بالنظر، والوعي عم يخفّ. أقرب تشخيص:","o":["Migraine عادية (شقيقة)","Angor (ذبحة صدرية)","HTIC (ارتفاع الضغط داخل الجمجمة)"],"a":2,"x":"céphalée + vomissement + troubles visuels + تراجع الوعي = HTIC."},{"id":"q114","t":"htic","q":"أي تدخّل صحيح بالـ HTIC؟","o":["راس مرفوع ٣٠° + Mannitol حسب الوصفة + مراقبة Glasgow","نزّل الراس لتحت ليوصل دم أكتر عالدماغ","PL فوراً لنخفّف الضغط بالجمجمة"],"a":0,"x":"tête surélevée، Mannitol، مراقبة الوعي، entrées/sorties. الـ PL ممنوع."},{"id":"q115","t":"htic","q":"مريض على warfarine (anticoagulant)، شو نصيحة الأكل من الصف؟","o":["ما يكتّر الخضار الخضرا (فيها vitamine K)","ياكل خضرا كتير كل يوم (فيها vitamine K)","يوقف المي والسوايل كلياً"],"a":0,"x":"الفيتامين K بيعاكس مفعول الـ anti-vitamine K."},{"id":"q116","t":"glasgow","q":"مريض: عيون ٢، كلام ٢، حركة ٤. قديش الـ Glasgow؟","o":["١٠","٨","٦"],"a":1,"x":"٢+٢+٤ = ٨ ← ٨ وما دون = coma."},{"id":"q117","t":"glasgow","q":"أعلى علامة للـ Moteur (الحركة) بالـ Glasgow:","o":["٤","٥","٦"],"a":2,"x":"Yeux ٤، Verbal ٥، Moteur ٦ — المجموع ١٥."},{"id":"q118","t":"glasgow","q":"Glasgow الطبيعي لشخص واعي تماماً:","o":["١٠","١٥","٣"],"a":1,"x":"من ٣ لـ ١٥. ١٥ = واعي تماماً."},{"id":"q119","t":"glasgow","q":"مريض Glasgow تبعو ٧. شو يعني؟","o":["Coma (غيبوبة) — خطر عالتنفّس","نعسان شوي بس — منخلّيه ينام","وعي طبيعي — ما في خطر"],"a":0,"x":"٨ وما دون = coma."},{"id":"q120","t":"henderson","l":"h1","q":"مريض MI بيتعب ويلهث بس يمشي للحمّام. أي حاجة Henderson متأثّرة؟","o":["Se récréer (يتسلّى)","Agir selon ses croyances (دينه وقيمه)","Se mouvoir (يتحرّك) ← Intolérance à l'activité"],"a":2,"x":"الحاجة ٤ Se mouvoir — NANDA: Intolérance à l'activité."},{"id":"q121","t":"henderson","l":"h2","q":"مريض pacemaker ما بيعرف ليش ممنوع يرفع إيدو ولا شو يعمل بالمطار. أي حاجة؟","o":["Éviter les dangers (يتجنّب المخاطر)","Apprendre (يتعلّم) ← Manque de connaissances","Dormir et se reposer (ينام ويرتاح)"],"a":1,"x":"الحاجة ١٤ Apprendre — NANDA: Manque de connaissances."},{"id":"q122","t":"henderson","l":"h1","q":"مريض endocardite حرارتو ٣٩. أي حاجة؟","o":["Communiquer (يتواصل) ← Communication altérée","Maintenir la température (يحافظ على حرارتو) ← Hyperthermie","Boire et manger (يشرب وياكل) ← Dénutrition"],"a":1,"x":"الحاجة ٧ — Hyperthermie."},{"id":"q123","t":"henderson","l":"h2","q":"مريض على héparine، في خطر نزيف ووقعة. أي حاجة؟","o":["Se récréer (يتسلّى ويرتاح)","Se vêtir et se dévêtir (يلبس ويشلح)","Éviter les dangers (يتجنّب المخاطر)"],"a":2,"x":"الحاجة ٩ — Risque de saignement، Risque de chute."},{"id":"q124","t":"henderson","l":"h2","q":"مريض AVC عندو aphasie وما بيقدر يعبّر عن وجعو. أي حاجة؟","o":["Éliminer (يخرّج) ← Rétention urinaire","Communiquer (يتواصل) ← Communication verbale altérée","Respirer (يتنفّس) ← Dyspnée"],"a":1,"x":"الحاجة ١٠ Communiquer."},{"id":"q125","t":"henderson","l":"h1","q":"مريض بعد laminectomie عندو احتباس بول. أي حاجة؟","o":["Éliminer (يخرّج) ← Rétention urinaire","Respirer (يتنفّس) ← Dyspnée","Dormir (ينام) ← Insomnie"],"a":0,"x":"الحاجة ٣ Éliminer."},{"id":"q126","t":"henderson","l":"h2","q":"مريض بالمستشفى بدّو يصلّي ويصوم. أي حاجة؟","o":["Se mouvoir et maintenir une bonne posture (يتحرّك)","Apprendre (يتعلّم عن مرضو وعلاجو)","Agir selon ses croyances et valeurs (يعيش حسب دينه وقيمه)"],"a":2,"x":"الحاجة ١١ — نحترم ونساعد."},{"id":"q127","t":"henderson","l":"h1","q":"مريض IC بيفيق بالليل بضيق نفس وما بينام منيح. أي حاجتين أكتر متأثّرين؟","o":["Respirer + Dormir et se reposer (يتنفّس + ينام ويرتاح)","Se récréer + Communiquer (يتسلّى + يتواصل)","Apprendre + Se vêtir (يتعلّم + يلبس)"],"a":0,"x":"ضيق النفس = Respirer، وقلّة النوم = Dormir et se reposer."},{"id":"q128","t":"law","l":"l1","q":"شو الشرط المشترك بين الدرجات الأربعة (متخصص، ممرض، فني، مساعد) تا يشتغلوا؟","o":["شهادة ماستر بالتمريض من جامعة معترف بها","إذن مزاولة مهنة من وزارة الصحة العامة + الكفاءات المحددة قانوناً","إذن من نقابة الممرضات والممرضين بس، بلا وزارة"],"a":1,"x":"كل الأربعة بدهن إذن مزاولة مهنة من وزارة الصحة العامة + الكفاءات المحددة قانوناً."},{"id":"q129","t":"law","l":"l1","q":"شو شهادة الممرض المتخصص؟","o":["إجازة جامعية بالعلوم التمريضية + ماستر على الأقل، من جامعة/كلية/معهد جامعي معترف به","ماستر بأي اختصاص من وزارة التربية، بلا إجازة بالتمريض ولا تدريب","إجازة فنية + ٥ سنين خبرة بالمستشفى، بلا شهادة جامعية ولا ماستر"],"a":0,"x":"أول إجازة جامعية بالتمريض، وبعدها ماستر على الأقل — من مؤسسة جامعية معترف بها بلبنان أو ما يعادلها."},{"id":"q130","t":"law","l":"l1","q":"كم سنة أقل شي البرنامج الجامعي الأساسي تبع الممرض؟","o":["سنتين","٤ سنين","٣ سنين"],"a":2,"x":"الممرض: برنامج جامعي أساسي ٣ سنين أو أكتر + إجازة جامعية."},{"id":"q131","t":"law","l":"l1","q":"شو شهادة الممرض الفني؟","o":["بكالوريا فنية بالعناية التمريضية بس، بلا ولا إجازة ولا تعليم بعدها","تعليم مهني ٣ سنين أو أكتر بعد الثانوية أو البكالوريا الفنية + إجازة فنية رسمية","إجازة جامعية ٣ سنين بالعلوم التمريضية + ماستر من جامعة"],"a":1,"x":"الممرض الفني = تعليم مهني ≥٣ سنين ← إجازة فنية رسمية من المديرية العامة للتعليم المهني والتقني. البكالوريا الفنية هيي شهادة مساعد الممرض."},{"id":"q132","t":"law","l":"l1","q":"مين اللي بيشتغل تحت إشراف ممرض متخصص أو ممرض أو ممرض فني؟","o":["مساعد الممرض","الممرض الفني","الممرض"],"a":0,"x":"«تحت الإشراف» = مساعد الممرض بس. الممرض الفني بيشتغل «بالمشاركة» مع الممرض والفريق."},{"id":"q133","t":"law","l":"l1","q":"أي درجة إلها دور تخطيطي وقيادي مع الفريق الطبي والصحي والإداري؟","o":["الممرض الفني","الممرض","الممرض المتخصص"],"a":2,"x":"الممرض المتخصص: تخطيطي وقيادي، بالإضافة لمهام الممرض."},{"id":"q134","t":"law","l":"l1","q":"وحدة من هول مش من مهام الممرض المتخصص الأربعة:","o":["المساهمة بوضع المناهج الأكاديمية والعملية","تطبيق الأنشطة المسندة إليه تحت الإشراف","إجراء الدراسات والأبحاث العلمية"],"a":1,"x":"تطبيق الأنشطة المسندة تحت الإشراف من مهام مساعد الممرض. مهام المتخصص: عناية متقدمة، المناهج، الأبحاث، إبداء الرأي للمؤسسة."},{"id":"q135","t":"law","l":"l1","q":"مساعد الممرض لازم يعمل كمان تواصل فعّال و…؟","o":["توثيق بدقّة ضمن إطار عمله","وضع المناهج الأكاديمية","تحديد الأنشطة اللي بتنسند للفريق"],"a":0,"x":"مهام مساعد الممرض الخمسة: تطبيق الأنشطة المسندة، الحماية من العدوى والمخاطر، تواصل فعّال، توثيق بدقّة ضمن إطار عمله، تقنيات تمريضية تحت الإشراف."},{"id":"q136","t":"law","l":"l1","q":"مين بيعطي لقب ممرض متخصص؟","o":["المديرية العامة للتعليم المهني والتقني","لجنة الاختصاص في التمريض — بعد إذن مزاولة مهنة ممرض","وزارة التربية"],"a":1,"x":"اللقب من لجنة الاختصاص في التمريض، بعد ما يكون معو إذن مزاولة مهنة ممرض."},{"id":"q137","t":"law","l":"l1","q":"مين بيجري الامتحان الرسمي للممرض الفني ومساعد الممرض؟","o":["نقابة الممرضات والممرضين بلبنان","وزارة الصحة العامة مع نقابة الممرضين","المديرية العامة للتعليم المهني والتقني"],"a":2,"x":"الامتحان الرسمي من المديرية العامة للتعليم المهني والتقني، ولطلاب المعاهد الخاصة كمان امتحان colloquium (امتحان الكفاءة)."},{"id":"q138","t":"law","l":"l1","q":"مين بيعطي إذن مزاولة مهنة التمريض بلبنان، ووين لازم يتسجّل الممرض إلزامياً؟","o":["وزارة الصحة العامة + نقابة الممرضات والممرضين","وزارة التربية + المديرية العامة للتعليم المهني والتقني","نقابة الممرضات والممرضين + وزارة العمل"],"a":0,"x":"ما حدا بيمارس التمريض ولا بياخد اللقب إلا بإذن مزاولة من وزارة الصحة العامة، وبيتسجّل إلزامياً بنقابة الممرضات والممرضين بلبنان."},{"id":"q139","t":"law","l":"l1","q":"شو مش من شروط إذن مزاولة المهنة للممرض اللبناني؟","o":["يكون لبناني وعمرو ١٨ سنة","غير محكوم بجناية أو محاولة جناية أو جنحة شائنة","يكون اشتغل سنتين بمستشفى قبل الإذن"],"a":2,"x":"الشروط: لبناني + ١٨ سنة، شهادة تمريض (أو من برّا بعد معادلتها)، كفاءات صحية وعقلية وأخلاقية، غير محكوم، ونجاح بامتحان الـ colloquium. ما في شرط خبرة."},{"id":"q140","t":"law","l":"l1","q":"ممرض لبناني أخد شهادتو من برّا. شو لازم يعمل فيها ليقدر ياخد إذن المزاولة؟","o":["ولا شي، بتنقبل متل ما هيي","يعادلها حسب الأصول","يعيد كل الدراسة بلبنان"],"a":1,"x":"الشرط: شهادة تمريض من لبنان، أو من الخارج بعد معادلتها وفقاً للأصول."},{"id":"q141","t":"law","l":"l2","q":"قدّيش مدّة البريفيه المهنية (BP)؟","o":["٩ أشهر","٣ سنين","سنة ونص"],"a":0,"x":"الـ BP = ٩ أشهر دراسة بعد الشهادة المتوسطة اللبنانية. الـ LT والـ BT كل وحدة ٣ سنين."},{"id":"q142","t":"law","l":"l2","q":"حامل البريفيه المهنية (BP) بياخد إذن مزاولة مهنة بصفة:","o":["ممرض فني","مساعد ممرض","معاون صحي"],"a":2,"x":"الـ BP ← إذن مزاولة مهنة بصفة معاون صحي وفق الوصف الوظيفي."},{"id":"q143","t":"law","l":"l2","q":"امتحان الـ colloquium (الامتحان الوطني) بالإجازة الفنية (LT) هوّي لمين؟","o":["لكل الطلاب بالمعاهد الرسمية بس","لطلاب المعاهد الخاصة","للي معن ماستر"],"a":1,"x":"الـ LT: امتحان رسمي بآخر الدراسة للكل (رسمي أو خاص)، + امتحان وطني colloquium لطلاب المعاهد الخاصة."},{"id":"q144","t":"law","l":"l2","q":"البكالوريا الفنية (BT) بتبلّش بعد شو؟","o":["بعد الإجازة الجامعية بالتمريض","بعد الثانوية العامة بس (البكالوريا)","بعد الشهادة المتوسطة الرسمية أو البريفيه المهنية"],"a":2,"x":"الـ BT: ٣ سنين بعد نيل الشهادة المتوسطة الرسمية أو البريفيه المهنية، + الامتحان الرسمي تبع مديرية التعليم المهني والتقني."},{"id":"q145","t":"law","l":"l2","q":"الامتحان الرسمي للشهادات المهنية الثلاثة (LT، BT، BP) مين بيجريه؟","o":["مديرية التعليم المهني والتقني","وزارة الصحة العامة","نقابة الممرضات والممرضين"],"a":0,"x":"كلّهن امتحانهن الرسمي من مديرية التعليم المهني والتقني. وزارة الصحة بتعطي إذن المزاولة، والنقابة للتسجيل."},{"id":"q146","t":"mgmt","l":"m1","q":"الدافع للعمل حسب خصائص الدوافع:","o":["منقدر نشوفو مباشرة بالعين بتصرّفات الشخص","ما منقدر نشوفو، بس منقدر نستنبطو (نستنتجو)","بس المدير بيقدر يشوفو بالتقييم السنوي"],"a":1,"x":"لا يمكن رؤية الدافع للعمل، بل يمكن إستنباطه (استنتاجه) من السلوك."},{"id":"q147","t":"mgmt","l":"m1","q":"حاجات وتوقعات الإنسان هي:","o":["متعددة ومتغيرة باستمرار، وممكن تتضارب","وحدة وثابتة طول العمر","متعددة بس ما بتتغيّر أبداً"],"a":0,"x":"للإنسان حاجات أو توقعات متعددة ومتغيرة بإستمرار وقد تتضارب."},{"id":"q148","t":"mgmt","l":"m1","q":"ليش عملية الدوافع معقّدة؟","o":["لأن كل الناس بيشبعو حاجاتهم بنفس الطريقة","لأن الإنسان ما عندو حاجات","لأن الأفراد بيشبعو حاجاتهم بطرق مختلفة"],"a":2,"x":"يشبع الأفراد حاجاتهم بطرق مختلفة، مما يزيد العملية تعقيداً."},{"id":"q149","t":"mgmt","l":"m1","q":"لما تنشبع حاجة عند إنسان، شو ممكن يصير؟","o":["بتنطفى دايماً وما بترجع","ممكن تزيد قوّتها، مش تنطفى","بتتحوّل لحاجة فيزيولوجية"],"a":1,"x":"إشباع حاجة ما قد يؤدي إلى إزدياد في قوة تلك الحاجة، وليس إلى إطفائها."},{"id":"q150","t":"mgmt","l":"m1","q":"ليش السلوك الهادف ما بيشبع الحاجات بكل الأحوال؟","o":["بسبب عقبات بتعترضو، فبيصير سلوك آخر غير اللي بيشبع الحاجة","لأن الحاجات ما بتتغيّر أبداً عند الإنسان طول حياتو","لأن الدافع منشوفو بالعين، فبيعرفو الناس ويمنعوه"],"a":0,"x":"السلوك الهادف لا يشبع في جميع الأحوال حاجات الإنسان بسبب العقبات، مما يؤدي إلى سلوك آخر غير السلوك الذي يشبع الحاجات."},{"id":"q151","t":"mgmt","l":"m1","q":"شو بقمّة هرم Maslow؟","o":["الحاجات الفيزيولوجية (physiological)","الحاجة للأمان (safety)","الحاجة إلى إثبات الذات (self-actualization)"],"a":2,"x":"القمة = الحاجة إلى إثبات الذات. الأساس = الحاجات الفيزيولوجية."},{"id":"q152","t":"mgmt","l":"m1","q":"الأكل، الشرب والنوم هني أمثلة على:","o":["الحاجات الفيزيولوجية (physiological) — أساس الهرم","الحاجة إلى الإحترام (esteem) — قبل القمة","الحاجة إلى العلاقات (social) — بنص الهرم"],"a":0,"x":"الحاجات الفيزيولوجية (الأكل، الشرب، النوم) هي أساس هرم Maslow."},{"id":"q153","t":"mgmt","l":"m1","q":"الزواج، الصداقة والعلاقات الإجتماعية بينتموا لـ:","o":["الحاجة للأمان (safety)","الحاجة إلى العلاقات (love/belonging)","الحاجة إلى إثبات الذات (self-actualization)"],"a":1,"x":"الحاجة إلى العلاقات: زواج، صداقة، علاقات إجتماعية (المستوى التالت من تحت)."},{"id":"q154","t":"mgmt","l":"m2","q":"مين فوق المدير بالهيكل التنظيمي للمستشفى؟","o":["الدائرة المالية","مجلس الإدارة","دائرة الجودة"],"a":1,"x":"مجلس الإدارة ← المدير ← الدوائر."},{"id":"q155","t":"mgmt","l":"m2","q":"حسب الهيكل، الإقتراحات بتروح على أي دائرة؟","o":["دائرة الجودة","الدائرة الطبية","دائرة الصيانة"],"a":0,"x":"سهم «إقتراحات» بالهيكل بيروح على دائرة الجودة."},{"id":"q156","t":"mgmt","l":"m2","q":"العلاقة بين رئيس قسم ورئيس قسم آخر اسمها:","o":["علاقة توجيهية","إقتراحات","علاقة تنسيقية"],"a":2,"x":"علاقة تنسيقية: بين رئيس قسم ورئيس قسم آخر."},{"id":"q157","t":"mgmt","l":"m2","q":"أي مثال هو علاقة توجيهية حسب دفترك؟","o":["رئيس قسم مع رئيس قسم آخر","مساعد ممرّض ومدير التمريض","الفوترة مع الدخول"],"a":1,"x":"علاقة توجيهية، مثلاً مساعد ممرّض ومدير التمريض. (رئيس قسم مع رئيس قسم = تنسيقية)"},{"id":"q158","t":"mgmt","l":"m2","q":"شو الأقسام التلاتة تحت الدائرة المالية؟","o":["القسم المالي، قسم التدقيق، القسم الحسابي","الفوترة، الدخول، الصندوق، والاستقبال","HR، الصيانة، الجودة، والمشتريات"],"a":0,"x":"الدائرة المالية ← القسم المالي، قسم التدقيق، القسم الحسابي."},{"id":"q159","t":"mgmt","l":"m2","q":"شو تحت القسم الحسابي؟","o":["القسم المالي وقسم التدقيق","أمين الصندوق بس","الفوترة، الدخول، الصندوق"],"a":2,"x":"القسم الحسابي ← الفوترة، الدخول، الصندوق."},{"id":"q160","t":"mgmt","l":"m2","q":"مين مباشرة تحت أمين الصندوق؟","o":["مساعد أمين الصندوق","القسم الحسابي","المدير"],"a":0,"x":"الصندوق ← أمين الصندوق ← مساعد أمين الصندوق."},{"id":"q161","t":"mgmt","l":"m2","q":"HR بالهيكل التنظيمي هي:","o":["دائرة الجودة (Quality department)","دائرة الموارد البشرية (Human resources)","الدائرة المالية (Finance department)"],"a":1,"x":"HR = دائرة الموارد البشرية، وحدة من الدوائر التمانية تحت المدير."},{"id":"q162","t":"quality","l":"q1","q":"نموذج دونابديان (Donabedian Model) لتقييم الجودة بيرتكز على تلات عناصر:","o":["الهيكل، سير العمل / العملية، النتائج","التخطيط، المراقبة، التحسين المستمر","التركيز على الزبون، العمل الجماعي، التحسين المستمر"],"a":0,"x":"Donabedian: ① الهيكل Structure ② سير العمل / العملية Process ③ النتائج Results."},{"id":"q163","t":"quality","l":"q1","q":"فلسفة جوران (Juran) بترتكز على:","o":["مواءمة الجودة مع المتطلبات بس","التخطيط، المراقبة، والتحسين المستمر","الهيكل والنتائج"],"a":1,"x":"ترتكز فلسفة جوران على ثلاثة عناصر: أولاً التخطيط، ثانيًا المراقبة، ثالثًا التحسين المستمر."},{"id":"q164","t":"quality","l":"q1","q":"فلسفة كروسبي (Crosby) بترتكز على مبدأ:","o":["العصف الذهني مع فريق العمل","قياس النتائج بالإحصائيات والرسوم البيانية","مواءمة الجودة مع المتطلبات مع اتخاذ الإجراءات الوقائية"],"a":2,"x":"Crosby: مواءمة الجودة مع المتطلبات، مع اتخاذ الإجراءات الوقائية بهدف الحد من العيوب ومنع حدوثها."},{"id":"q165","t":"quality","l":"q1","q":"إدارة الجودة الشاملة هي فلسفة إدارية بترتكز على تلات مبادئ أساسية:","o":["التخطيط، التنفيذ، والأرشفة الإلكترونية للملفات","التركيز على الزبون، العمل الجماعي، التحسين المستمر","الهيكل، العملية، النتائج (Donabedian)"],"a":1,"x":"إدارة الجودة الشاملة: التركيز على الزبون، العمل الجماعي، التحسين المستمر."},{"id":"q166","t":"quality","l":"q2","q":"مراحل دورة ديمينغ / PDCA بالترتيب:","o":["خطط Plan ← نفّذ Do ← تحقق Check ← اعمل Act","نفّذ Do ← خطط Plan ← اعمل Act ← تحقق Check","تحقق Check ← خطط Plan ← نفّذ Do ← اعمل Act"],"a":0,"x":"دورة شيوهارت / Deming / PDCA: خطط Plan، نفّذ Do، تحقق Check، اعمل Act."},{"id":"q167","t":"quality","l":"q2","q":"مخطط باريتو (Pareto) منطلق من نظرية إنو:","o":["50% من الأسباب لها تأثير على 50% من النتائج","كل سبب إلو نفس التأثير","20% من الأسباب لها تأثير على 80% من النتائج"],"a":2,"x":"Pareto: انطلاقًا من نظرية أن 20% من الأسباب لها تأثير على 80% من النتائج."},{"id":"q168","t":"quality","l":"q2","q":"جسم السمكة بمخطط إشيكاوا فيه ٤ فروع للمسببات:","o":["Plan، Do، Check، Act","Method، Machine، Manpower، Material","Strengths، Weaknesses، Opportunities، Threats"],"a":1,"x":"هيكل السمكة: Method الطريقة، Machine الآلة، Manpower القوى البشرية، Material المواد."},{"id":"q169","t":"quality","l":"q4","q":"كيف منحسب المؤشر؟","o":["عدد الحالات المتكررة × 100 ÷ العدد الإجمالي للعينة ضمن مدة زمنية محددة","العدد الإجمالي للعينة ÷ 100 بلا ما نحسب الحالات المتكررة","عدد الموظفين × عدد المرضى بالقسم خلال الشهر"],"a":0,"x":"المؤشر = عدد الحالات المتكررة × 100 ÷ العدد الإجمالي للعينة ضمن مدة زمنية محددة."},{"id":"q170","t":"quality","l":"q5","q":"السياسة بتجاوب عن سؤال «ماذا؟»، والإجراءات بتجاوب عن:","o":["متى؟","مين؟","كيف؟"],"a":2,"x":"السياسة = ماذا يجب أن نعمل؟ الإجراءات = كيف ننفذ العمل؟ (خطوات عملية لتنفيذ السياسة)."},{"id":"q171","t":"quality","l":"q3","q":"بـ SWOT، حرف O يعني:","o":["Objectives = الأهداف: يلي المؤسسة بدها توصلها","Opportunities = الفرص: عوامل خارجية يمكن استغلالها للتطور والنجاح","Obstacles = العوائق: مشاكل داخلية بتوقّف التطور"],"a":1,"x":"SWOT: S نقاط القوة، W نقاط الضعف، O الفرص (خارجية)، T التهديدات (خارجية)."},{"id":"q172","t":"quality","l":"q7","q":"RCA (Root Causes Analysis) يعني:","o":["تحليل الأسباب الجذرية للمشكلة، لتحديد استراتيجيات وقائية","مراقبة رضا المرضى من خلال استمارات بعد الخروج","ترقيم السياسات والإجراءات حسب الفئة الوظيفية"],"a":0,"x":"RCA = تحليل الأسباب الجذرية للمشكلة: لماذا حدث الفشل؟ وما سببه؟ لتحديد الإجراء الوقائي."},{"id":"q173","t":"quality","l":"q8","q":"الاعتماد (Accréditation) هو:","o":["تفتيش إلزامي من وزارة المالية بيصير كل سنة على كل المستشفيات","تقييم داخلي بيعملو المدير لحالو بلا أي جهة من برّا","عملية تقييم طوعي تقوم بها جهة تقييم خارجية مستقلة، وبتعطي اعترافًا مؤقتًا بالكفاءة"],"a":2,"x":"الاعتماد: عملية تقييم طوعي تقوم بها جهة تقييم خارجية مستقلة… ويمنح الاعتماد المؤسسة اعترافًا مؤقتًا بكفاءتها."},{"id":"q174","t":"pharma","l":"coag","q":"Actilyse / Streptase من أي عائلة؟","o":["Thrombolytique (مذيب للجلطات)","Anticoagulant (مضاد تخثر)","Bêtabloquant (حاضرات البيتا)"],"a":0,"x":"Actilyse, Streptase, Alteplase, Streptokinase = Thrombolytique، مذيب للجلطات (Lyse de caillot، تحلل الجلطة)."},{"id":"q175","t":"pharma","l":"atb","q":"مريض عم ياخد Amikin (Amikacin، Aminoside): شو لازم نراقب؟","o":["Surveillance de la glycémie (السكر بالدم) بس","Surveillance de l’audition + fonction rénal (السمع ووظيفة الكلى)","حدقة العين وحركتها (Pupilles) والنظر"],"a":1,"x":"Amikin: Surveillance de l’audition (مراقبة السمع)، Test d’allergie، Surveillance de fonction rénal (متابعة وظيفة الكلى)."},{"id":"q176","t":"pharma","l":"cardio","q":"Lasix (Furosémide) شو بيعمل؟","o":["Bronchodilatateur (موسّع للقصبات)","Antiémétique (مضاد للتقيؤ)","Diurétique de l’anse (مدر بولي)"],"a":2,"x":"Lasix = Furosémide، Sulfamide، Diurétique de l’anse (مدر بولي). منراقب الكهارل والضغط."},{"id":"q177","t":"pharma","l":"cardio","q":"Lanoxin / Digoxin من أي عائلة؟","o":["Statine (للكوليسترول)","Glycoside cardiaque","Biguanides (للسكري)"],"a":1,"x":"Lanoxin / Digoxin = Glycoside cardiaque: يزيد قوة انقباض القلب، ينظم ويبطئ. منراقب مستوى Digoxin بالدم ونظم القلب."},{"id":"q178","t":"pharma","l":"coag","q":"Sintrom هو:","o":["Antivitamine K (مضاد لفيتامين ك) — Anticoagulant","Inhibiteur de la pompe à proton — Anti-ulcéreux","Corticostéroïde (كورتيزون) — Anti-inflammatoire"],"a":0,"x":"Sintrom = Antivitamine K، Anticoagulant (مضاد تخثر). تجنب الشفرة الكهربائية + مراقبة علامات النزيف."},{"id":"q179","t":"pharma","l":"coag","q":"مع Héparine وLovenox، شو من دور الممرض؟","o":["نشجّع المريض يحلق بالموس العادي كل يوم","نراقب الوزن بس، والنزيف مش مهم","Eviter rasoir électrique + surveiller les signes d’hémorragie"],"a":2,"x":"Héparine / Lovenox: مراقبة ضغط الدم، تجنب استعمال الشفرة الكهربائية، مراقبة علامات النزيف."},{"id":"q180","t":"pharma","l":"dig","q":"Losec وRisek (Oméprazol) شو هني؟","o":["Antibiotiques (مضادات حيوية ضد البكتيريا)","Inhibiteur de la pompe à proton (مثبط مضخة البروتون)","Anxiolytique (مضاد للقلق والتوتر)"],"a":1,"x":"Losec / Risek = Oméprazol: IPP، Inhibiteur de la pompe à proton (مثبط مضخة البروتون)."},{"id":"q181","t":"pharma","l":"resp","q":"Ventoline (Salbutamol):","o":["Bronchodilatateur (موسع للقصبات الهوائية)، منراقب النبض والتنفس","Diurétique (مدرّ للبول)، منراقب البول والبوتاسيوم","Hypo-uricémiant (بينزّل حمض البول)، منراقب المفاصل"],"a":0,"x":"Ventoline = Salbutamol، Bronchodilatateur. Surveillance de pouls + de la respiration."},{"id":"q182","t":"pharma","l":"cardio","q":"Temormin (Aténolol) Bêtabloquant: شو من موانع الاستعمال؟","o":["Hypertension artérielle (ارتفاع الضغط) و Angor","Arythmie (اضطراب ضربات القلب) و Tachycardie","Bradycardie (بطء في ضربات القلب) و Asthme sévère"],"a":2,"x":"Temormin CI: Allaitement، Bradycardie، Asthme sévère، Acidose métabolique، Hypotension. (الـ HTA والـ Arythmie هني indications)."},{"id":"q183","t":"pharma","l":"diab","q":"Metformin (Glucophage) من عائلة:","o":["Sulfamide — Antibiotique","Biguanides — Antidiabétique oral","Aminoside — Antibiotique"],"a":1,"x":"Metformin = Biguanides، Antidiabétique oral Hypoglycémiante. منراقب السكر ووظائف الكلى والكبد."},{"id":"q184","t":"pharma","l":"dig","q":"Zofran (Ondansétron) بينعطى لـ:","o":["Antiémétique: الغثيان والتقيؤ من العلاج الكيميائي أو الإشعاعي","Anticoagulation: منع الجلطات بالشرايين والأوردة","Mucolytique: تذويب البلغم بالصدر والقصبات"],"a":0,"x":"Zofran = Ondansétron، Antiémétique Antinauséeux، للوقاية والعلاج من الغثيان والتقيؤ الناتجين عن العلاج الكيميائي أو الإشعاعي."},{"id":"q185","t":"pharma","l":"other","q":"Valium شو اسمو العلمي؟","o":["Tramadol","Kétoprofène","Diazépam"],"a":2,"x":"Valium = Diazépam: Myorelaxante، Anxiolytique، Sédative… منراقب علامات الإدمان ونتجنب الاستخدام المطول."},{"id":"q186","t":"heart","q":"الدم بلا أوكسجين بيرجع من الجسم عبر الـ Veine cave (الوريد الأجوف). على أي حجرة بيفوت أوّل شي؟","o":["Oreillette gauche (الأذين الأيسر)","Oreillette droite (الأذين الأيمن)","Ventricule gauche (البطين الأيسر)"],"a":1,"x":"Veine cave ← Oreillette droite ← Valve tricuspide ← Ventricule droit ← Artère pulmonaire ← الرية. الأذين الأيسر بيستقبل الدم <b>مع</b> أوكسجين من الـ Veines pulmonaires."},{"id":"q187","t":"heart","q":"أي حجرة بالقلب جدارها هوّي الأسمك، وليش؟","o":["Ventricule gauche (البطين الأيسر) — لأنو بيضخّ لكل الجسم","Ventricule droit (البطين الأيمن) — لأنو بيضخّ للرية","Oreillette droite (الأذين الأيمن) — لأنو بيستقبل دم كل الجسم"],"a":0,"x":"الـ Ventricule gauche جدارو الأسمك لأنو بيضخّ الدم عبر الـ Valve aortique والـ Aorte (الأبهر) لكل الجسم."},{"id":"q188","t":"heart","q":"الـ Débit cardiaque (الناتج القلبي) بيساوي:","o":["Tension artérielle (الضغط) × Fréquence respiratoire (التنفّس)","Volume d'éjection (حجم الضربة) ÷ Fréquence cardiaque (النبض)","Fréquence cardiaque (عدد النبضات) × Volume d'éjection (حجم الضربة)"],"a":2,"x":"Débit cardiaque = Fréquence cardiaque × Volume d'éjection. أي مرض بيضعّف واحد منهن بيأثّر على الدماغ والرية والأطراف، وهيدا بيفسّر العوارض."},{"id":"q189","t":"brain","q":"أي قسم من الدماغ مسؤول عن التوازن والتنسيق، ومشكلتو بتعطي ataxie (ترنّح بالمشي)؟","o":["Lobe occipital (الفص القذالي)","Cervelet (المخيخ)","Lobe temporal (الفص الصدغي)"],"a":1,"x":"الـ Cervelet (المخيخ) تحت ولورا: التوازن والتنسيق. الـ Lobe occipital للنظر، والـ Lobe temporal للسمع والذاكرة."},{"id":"q190","t":"brain","q":"ليش الـ HTIC خطيرة، حسب تشريح الدماغ؟","o":["لأنو الدماغ ممكن ينحشر (engagement) ويضغط على الـ Tronc cérébral (جذع الدماغ) يلي فيه مراكز التنفّس ودقات القلب","لأنها بتضغط بس على الـ Lobe occipital (الفص القذالي) فبتأثّر عالنظر وما بتعمل شي تاني","لأنها بتسكّر الـ Moelle épinière (النخاع الشوكي) عند L4–L5 فبيصير شلل بالإجرين"],"a":0,"x":"الـ Tronc cérébral (mésencéphale، pont، bulbe rachidien) فيه مراكز التنفّس ودقات القلب، وبالـ HTIC الدماغ ممكن ينحشر (engagement) ويضغط عليه."},{"id":"q191","t":"brain","q":"وين منعمل الـ ponction lombaire (البزل القطني)، وليش؟","o":["بين L1–L2 — لأنو هونيك أوسع مكان بين الفقرات","فوق L1 — لأنو أقرب للدماغ، فمنوصل للـ LCR أسرع","بين L3–L4 أو L4–L5 — لأنو النخاع بيخلص تقريباً عند L1–L2"],"a":2,"x":"الـ Moelle épinière بيخلص تقريباً عند L1–L2، وتحت في LCR وأعصاب بس، لهيك البزل بين L3–L4 أو L4–L5 — بعيد عن النخاع."},{"id":"q192","t":"quality","l":"q3","q":"بطريقة SMART لتحديد الأهداف، حرف M يعني:","o":["Measurable = قابل للقياس: منقدر نقيس قديش تحقّق بالأرقام أو النتائج","Meaningful = إلو معنى عند الموظفين وبيحمّسهن عالشغل","Managed = بيديرو مسؤول القسم وبيتابعو كل يوم"],"a":0,"x":"SMART: Specific محدد، Measurable قابل للقياس، Achievable قابل للتحقيق، Relevant ذو صلة، Time-bound محدد بزمن."},{"id":"q193","t":"quality","l":"q3","q":"الرسالة (المهمة) بالخطة الاستراتيجية هي:","o":["شو بيتطلّع إليه المدراء","الأعمال والخدمات المقدّمة من المؤسسة، وبتوضّح ليش وُجد المشروع","مبادئ إرشادية بتساعد على اتخاذ القرارات متل الحياد والاستقامة"],"a":1,"x":"الرسالة = ليش موجودة المؤسسة. الرؤية = شو بيتطلّع إليه المدراء. القيم = مبادئ إرشادية (الحياد، الاستقامة)."},{"id":"q194","t":"quality","l":"q3","q":"مخطط سير العمل بالخطة الاستراتيجية بيكون لمدة:","o":["سنة وحدة، ويشمل التوظيف والتدريب بس","عشر سنين، ويشمل بناء المستشفى والأقسام","تلات سنين، ويشمل التخطيط، البرمجة، والميزانية"],"a":2,"x":"مراحل الخطة الاستراتيجية: أ- الرؤية (بعد تحليل البيئة وتحديد الأهداف)، ب- مخطط سير العمل لمدة ٣ سنوات: تخطيط، برمجة، ميزانية."},{"id":"q195","t":"quality","l":"q4","q":"لوضع أي مؤشر لازم نحدّد تلات عناصر (الأسئلة المفتاحية):","o":["الظاهرة موضوع الدراسة، العينة البشرية، المدة الزمنية","الهيكل، سير العمل، والنتائج (Donabedian)","الرسالة، الرؤية، والقيم تبع المؤسسة"],"a":0,"x":"عناصر المؤشر الأساسية: الظاهرة + العينة البشرية + المدة الزمنية. (الهيكل/العملية/النتائج = نموذج Donabedian)."},{"id":"q196","t":"quality","l":"q4","q":"المؤشر (Indicateur) هو:","o":["توجيهات مكتوبة بتجاوب عن سؤال ماذا؟ وبتحدّد شو لازم نعمل بالمؤسسة","أداة قياس رقمية بتعطي النسبة المئوية لمدى حدوث ظاهرة أو حالة بشكل تراكمي","تقييم طوعي بتعملو جهة خارجية مستقلة وبيعطي اعتراف مؤقت"],"a":1,"x":"المؤشر = أداة قياس رقمية (نسبة مئوية) لظاهرة بشكل تراكمي. «ماذا؟» = السياسة، والتقييم الطوعي الخارجي = الاعتماد."},{"id":"q197","t":"quality","l":"q4","q":"المؤشرات لازم تنحط وفق طريقة:","o":["SWOT","Pareto","SMART"],"a":2,"x":"من خصائص المؤشر: وضع المؤشرات وفق طريقة SMART، يكون سهل الفهم والاستخدام، والثبات."},{"id":"q198","t":"quality","l":"q5","q":"الرقم المرجعي لسياسة أو إجراء (متل COP-MUL-001) بيتألّف من:","o":["تلات أقسام: ٣ أحرف للفئة الوظيفية، ٣ أحرف للفئة المعنية، ورقم تسلسلي من ٣ أرقام","قسمين: اسم القسم كامل وتاريخ الإصدار باليوم والشهر والسنة","رقم تسلسلي بس من ٣ أرقام بلا ولا حرف قبلو"],"a":0,"x":"COP-MUL-001 = Care of Patient – Multi Units – 001: فئة وظيفية + فئة معنية + رقم تسلسلي."},{"id":"q199","t":"quality","l":"q5","q":"بترقيم السياسات، PFR يعني:","o":["Assessments of Patients = تقييم المريض","Patient and Family Rights = حقوق المريض والعائلة","Access to Care = الوصول إلى الرعاية"],"a":1,"x":"PFR = حقوق المريض والعائلة. AOP = تقييم المريض. ACC = الوصول إلى الرعاية واستمرارية الرعاية."},{"id":"q200","t":"quality","l":"q5","q":"مين بيراجع السياسات والإجراءات ليتأكّد إنها مطابقة للمعايير ويحدّدلها رقم مرجعي وتسلسل؟","o":["المريض وعائلته","قسم علاقات المرضى","مسؤول الاعتماد"],"a":2,"x":"مسؤول الاعتماد بيراجعها لضمان تطابقها مع المعايير ولتحديد رقم مرجعي وتسلسل، وكل قسم بيراجع السياسات الخاصة فيه."},{"id":"q201","t":"quality","l":"q6","q":"الوصف الوظيفي (Description de poste) هو:","o":["وصف مكتوب للعمل اللي بيعملو الموظف","تقييم سنوي لأداء الموظف","سجل الحضور والغياب للموظف"],"a":0,"x":"الوصف الوظيفي = وصف مكتوب للعمل: المسمّى، الأهداف، الواجبات والمسؤوليات، العلاقات الوظيفية، والمعرفة والمهارات اللازمة."},{"id":"q202","t":"quality","l":"q6","q":"المسؤولية بتصير لما يتوفّر تلات عناصر:","o":["الخطأ، الشكوى المكتوبة من المريض، والعقوبة من النقابة","الخطأ (إرادي أو غير إرادي)، الضرر، وارتباط السبب بالضرر","الضرر، وجود الشهود، والتعويض المادي للمريض"],"a":1,"x":"المسؤولية = حالة بيُسأل فيها الشخص عن عمل عملو، بشرط: مبدأ الخطأ + الضرر + ارتباط السبب بالضرر."},{"id":"q203","t":"quality","l":"q6","q":"المسؤولية الجزائية (Responsabilité pénale) هي اللي:","o":["بتستوجب التعويض عن خطأ شخصي نتج عنه ضرر","فيها مخالفة للنظام الداخلي لمؤسسة","فيها خرق قانوني بيستوجب العقوبة"],"a":2,"x":"مدنية = تعويض عن خطأ نتج عنه ضرر. جزائية = خرق قانوني بيستوجب العقوبة. مسلكية = مخالفة للنظام الداخلي للمؤسسة."},{"id":"q204","t":"quality","l":"q6","q":"من المصادر الأساسية لمسؤولية الممرض:","o":["إفشاء سر، أخذ مبادرة من خارج اختصاصه، وعدم مدّ يد المساعدة","تطبيق السياسات والإجراءات المكتوبة بالقسم","توثيق العناية التمريضية بالملف الطبي للمريض"],"a":0,"x":"مصادر مسؤولية الممرض: خطأ بالعناية، القتل بقصد، الجرح والضرب المقصود، مبادرة من خارج اختصاصه، إفشاء سر، التقصير عن الواجب، عدم مدّ يد المساعدة."},{"id":"q205","t":"quality","l":"q6","q":"مريض رفض العلاج. قبل ما يترك المستشفى لازم:","o":["نجبرو ياخد العلاج قبل ما يفلّ من المستشفى، حتى لو رافض","يوقّع نموذج رفض العلاج، بعد ما الطبيب المعالج يوضّحلو نتائج الرفض","ما في شي، بيفلّ بلا ولا ورقة ولا توقيع ولا شرح"],"a":1,"x":"حق المريض أو عيلتو برفض أي علاج، مع توضيح نتائج الرفض من الطبيب المعالج، وقبل مغادرة المستشفى بيوقّع نموذج رفض العلاج."},{"id":"q206","t":"quality","l":"q7","q":"FMEA يعني:","o":["Root Causes Analysis = تحليل الأسباب الجذرية","تحليل البيئة الداخلية والخارجية للمؤسسة","Failure Mode Effects and Analysis = تحليل أنماط الفشل وتأثيراته"],"a":2,"x":"FMEA = تحليل أنماط الفشل وتأثيراته: عملية استكشاف الأخطاء وإصلاحها. RCA = الأسباب الجذرية. تحليل البيئة = SWOT."},{"id":"q207","t":"quality","l":"q7","q":"سلامة المريض بتتحقّق من خلال:","o":["تحديد المخاطر، تقديرها، التعامل معها، وتقييم كيفية التعامل معها","تقليل عدد الممرضين بالقسم لنخفّف الأخطاء","ترقيم السياسات والإجراءات بس، بلا ما نتابع المخاطر"],"a":0,"x":"سلامة المريض = التقليل من الخطوات غير الآمنة، وبتتحقق بـ: تحديد المخاطر ← تقديرها ← التعامل معها ← تقييم التعامل."},{"id":"q208","t":"quality","l":"q7","q":"مفهوم إدارة المخاطر بيُعتبر استراتيجية:","o":["علاجية بعد ما يصير الحادث بس","وقائية","مالية لرفع الأرباح"],"a":1,"x":"إدارة المخاطر استراتيجية وقائية: الحد من الأخطار بطريقة استباقية."},{"id":"q209","t":"quality","l":"q7","q":"من مصادر الأخطاء الطبية:","o":["ملصقات توجيهية بأماكن الانتظار","مواعيد الزيارة المحددة","عوامل بشرية، تعقيد الإجراء، وفشل النظام الطبي"],"a":2,"x":"مصادر الأخطاء الطبية: عوامل بشرية + تعقيد الإجراء + فشل النظام الطبي."},{"id":"q210","t":"quality","l":"q8","q":"JCI (Joint Commission International) هي منظمة اعتماد عالمية من:","o":["USA","France","Canada"],"a":0,"x":"JCI = USA. ANAES = France. CCHSA = Canada. TAS = UK. ACHSI = Australia."},{"id":"q211","t":"quality","l":"q8","q":"من خطوات التحضير للاعتماد:","o":["إلغاء الملفات الطبية القديمة وأرشفتها","الحصول على نسخة من المعايير وإجراء تقييم ذاتي","تقليل عدد الموظفين بالأقسام"],"a":1,"x":"التحضير للاعتماد: نسخة من المعايير، تعيين مسؤول متابعة، تقييم ذاتي، تعريف المديرين والموظفين بفوائد الاعتماد، تحديد الثغرات…"},{"id":"q212","t":"quality","l":"q8","q":"اللجان بالمستشفى هي أفراد بيشتغلوا بشكل متكامل لهدف مشترك، ومين بيعيّنها؟","o":["المرضى","جهة الاعتماد الخارجية","الإدارة"],"a":2,"x":"اللجان مجموعة أفراد بتشتغل بشكل متكامل لهدف مشترك، وبيتم تعيينها من قبل الإدارة وبتشتغل تحت إشرافها."},{"id":"q213","t":"quality","l":"q9","q":"الملف الطبي إلو قيمة طبية وتمريضية وديموغرافية، وكمان قيمة ____ لأنه مرجع إذا صار مساءلة بين الأطراف:","o":["قانونية","تجارية","إعلانية"],"a":0,"x":"الملف الطبي هو الوثيقة الاستشفائية الأهم، ومستند قانوني بيشكّل مرجع بحال أي مساءلة."},{"id":"q214","t":"quality","l":"q9","q":"وحدة الأرشيف بتحفظ الملفات الطبية بمكان آمن لمدة:","o":["سنة وحدة","عشر سنين على الأقل","لحد ما يطلع المريض من المستشفى"],"a":1,"x":"من مسؤوليات وحدة الأرشيف: حفظ الملفات حسب الطرق العلمية بمكان آمن لمدة عشر سنوات على الأقل."},{"id":"q215","t":"quality","l":"q9","q":"قديش ملف طبي لازم يكون للمريض؟","o":["ملف جديد بكل مرة بيدخل","ملف للطوارئ وملف منفصل للعيادات الخارجية","ملف واحد مهما تعدّدت مرات دخوله للمستشفى"],"a":2,"x":"التأكد من وجود ملف طبي واحد للمريض الواحد، وتوحيد ملفات الطوارئ والعيادات الخارجية مع ملفات الاستشفاء."},{"id":"q216","t":"quality","l":"q9","q":"المريض بيحقلو ياخد نسخة من ملفه الطبي:","o":["بناءً على طلبه، وبعد موافقة الطبيب المعالج","أبداً، الملف سرّي حتى عن المريض","بس بأمر من المحكمة"],"a":0,"x":"يحق للمريض الحصول على نسخة من ملفه الطبي بناءً على طلبه وبعد موافقة الطبيب المعالج."},{"id":"q217","t":"pharma","l":"atb","q":"Claforan (Cefotaxime) من أي عائلة؟","o":["Céphalosporine 3ème génération (سيفالوسبورين جيل تالت)","Aminoside (أمينوزيد) — Antibiotique","Fluoroquinolone (فلوروكينولون) — Antibiotique"],"a":0,"x":"Claforan = Céphalosporine 3ème génération. Amikin / Gentamycine = Aminoside. Tavanic = Fluoroquinolone."},{"id":"q218","t":"pharma","l":"atb","q":"Flagyl (Métronidazole): شو من موانع الاستعمال (contre-indications)؟","o":["Infection gastro-intestinal (عدوى بالجهاز الهضمي) وإسهال","Consommation d’alcool (تناول الكحول)، Allaitement (الرضاعة)، وولد أقل من ٦ سنين","Vaginite (التهاب المهبل) وعدوى بالأسنان"],"a":1,"x":"Flagyl: Antibiotique + Antiseptique intestinal. الالتهابات المهبلية والهضمية هي استعمالاتو، وممنوع مع الكحول والرضاعة وتحت ٦ سنين."},{"id":"q219","t":"pharma","l":"atb","q":"قبل أول جرعة Rocephine (Ceftriaxone)، شو منعمل؟","o":["Surveillance de l’audition (مراقبة السمع) بس","فحص سكر بالدم","Test d’allergie (اختبار تحسس) للجرعة الأولى"],"a":2,"x":"Rocephine = Céphalosporine: Test d’allergie pour la 1ère dose، وممنوعة إذا في Allergie aux Céphalosporines."},{"id":"q220","t":"pharma","l":"resp","q":"Bisolvon (Bromhexine) شو بيعمل؟","o":["Mucolytique (مذيب للبلغم): بيسهّل طرد البلغم (expectoration)","Bronchodilatateur (موسّع للقصبات): بيوسّع مجرى الهوا","Antibiotique (مضاد حيوي): بيقتل البكتيريا بالرية"],"a":0,"x":"Bisolvon = Mucolytique، بيعدّل إفرازات الشعب الهوائية وبيسهّل طرد البلغم. منراقب السعال والبلغم."},{"id":"q221","t":"pharma","l":"resp","q":"مريض عم ياخد Pulmicort (Budésonide): شو أهم دور للممرض؟","o":["Surveillance de l’audition (مراقبة السمع) لأنو ممكن يعمل طرش","Soin de bouche (العناية بالفم) لأنو ممكن يعمل Candidose buccale (فطريات الفم)","Surveillance de la glycémie (السكر) بس، كل ساعة"],"a":1,"x":"Pulmicort = Corticoïde inhalé (مضاد التهاب ستيرويدي): مراقبة التنفس + العناية بالفم. أعراضو: Candidose buccale، Dysphonie (بحة)."},{"id":"q222","t":"pharma","l":"resp","q":"Atrovent (Ipratropium) من أي عائلة؟","o":["Corticoïde (كورتيزون) — Anti-inflammatoire","Mucolytique (مذيب للبلغم) — Expectorant","Anticholinergique (مضاد كوليني) — Bronchodilatateur"],"a":2,"x":"Atrovent = Anticholinergique، بيشتغل كـ Bronchodilatateur (موسّع للقصبات)."},{"id":"q223","t":"pharma","l":"diab","q":"Glutril / Diamicron من عائلة:","o":["Sulfamide — Hypoglycémiante (خافض للسكر)","Biguanides (بيغوانيد)","Céphalosporine (سيفالوسبورين)"],"a":0,"x":"Glutril / Diamicron = Sulfamide. Metformin / Glucophage = Biguanides."},{"id":"q224","t":"pharma","l":"diab","q":"Glutril / Diamicron ممنوع (contre-indiqué) بـ:","o":["Diabète non insulinodépendant (السكري غير المعتمد على الإنسولين)","Diabète insulinodépendant (السكري المعتمد على الإنسولين)","Antidiabétique orale (دوا سكري بالفم)"],"a":1,"x":"Glutril بينعطى بالـ Diabète non insulinodépendant، وممنوع بالـ insulinodépendant، والقصور الكلوي أو الكبدي الشديد، والرضاعة."},{"id":"q225","t":"pharma","l":"diab","q":"أخطر عارض جانبي لـ Metformin إذا في قصور كلوي أو كبدي:","o":["Candidose buccale (فطريات الفم)","Trouble de l’audition (مشكلة بالسمع)","Acidose lactique (الحماض اللاكتيكي)"],"a":2,"x":"Metformin: Acidose lactique بحال قصور كلوي أو كبدي، وكمان Hypoglycémie، غثيان، إسهال، طعم معدني بالتم. منراقب وظائف الكلى والكبد."},{"id":"q226","t":"pharma","l":"dig","q":"Duphalac (Lactulose) بينعطى لـ:","o":["Constipation (إمساك) وملازمة الفراش لفترة طويلة","Diarrhée (إسهال)","Reflux gastro-œsophagien (الارتجاع)"],"a":0,"x":"Duphalac = Anti-constipation. منراقب تكرار وكمية التبرّز وترطيب الجسم. من أعراضو: إسهال وانتفاخ."},{"id":"q227","t":"pharma","l":"dig","q":"Spasfon (Phloroglucinol) شو بيعمل؟","o":["Antiémétique (مضاد للتقيؤ): غثيان واستفراغ بعد العمليات","Antispasmodique (مضاد للتشنجات): مغص كلوي أو كبدي، وجع بطن، آلام الدورة","IPP (مثبط مضخة البروتون): حموضة وقرحة المعدة"],"a":1,"x":"Spasfon = Antispasmodique. Primpéran / Zofran = Antiémétique. Losec / Risek = IPP."},{"id":"q228","t":"pharma","l":"dig","q":"Primpéran (Métoclopramide) ممنوع (contre-indiqué) بـ:","o":["Nausée (غثيان) و Reflux (ارتجاع)","Vomissement (تقيؤ) و Gastroparésie","Epilepsie (الصرع) و Maladie de Parkinson (باركنسون)"],"a":2,"x":"Primpéran = Antiémétique للغثيان والتقيؤ. ممنوع: نزيف هضمي، الصرع، باركنسون، وولد أقل من سنة."},{"id":"q229","t":"pharma","l":"other","q":"Zyloric (Allopurinol) شو بيعمل؟","o":["Hypo-uricémiant: بيخفّض حمض البول (داء النقرس، Goutte)","Hypoglycémiant: بيخفّض السكر بالدم (Diabète)","Antispasmodique: بيخفّف المغص والتشنجات"],"a":0,"x":"Zyloric بيقلّل إنتاج حمض البول. استعمالاتو: النقرس، المغص الكلوي، ارتفاع حمض البول. منراقب حمض البول + شرب سوائل بكترة."},{"id":"q230","t":"pharma","l":"other","q":"Cytotec (Misoprostole) من استعمالاتو:","o":["Asthme (الربو) ونوبات ضيق النفس","Hémorragie de la délivrance (نزيف ما بعد الولادة)","Maladie de goutte (النقرس) ووجع المفاصل"],"a":1,"x":"Cytotec: إنهاء الحمل بالثلث الأول والتاني، إنضاج عنق الرحم، تحفيز الولادة، نزيف ما بعد الولادة. والربو من موانعو."},{"id":"q231","t":"pharma","l":"other","q":"مريض عم ياخد Valium (Diazépam): شو لازم نراقب؟","o":["Surveillance de l’audition (مراقبة السمع) ووظيفة الكلى","Na⁺ والسكر بالدم، ومنكمّل عليه سنين","Signes de dépendance (علامات الإدمان) والذاكرة، ومنتجنّب الاستعمال الطويل"],"a":2,"x":"Valium: Anxiolytique، Sédatif، Myorelaxant… من أعراضو: Trouble de mémoire و Dépendance."},{"id":"q232","t":"pharma","l":"pain","q":"Aspirine ممنوعة (contre-indiquée) بـ:","o":["Ulcère gastroduodénal (قرحة المعدة والاتني عشر) و Hémorragie (نزيف)","Fièvre (حرارة) و Céphalée (وجع راس) و Grippe (رشح)","Douleur (وجع) و Inflammation (التهاب) بالمفاصل"],"a":0,"x":"Aspirine = AINS: مضاد التهاب، خافض حرارة، مسكّن، ومضاد لتجمّع الصفائح. ممنوعة بالقرحة والنزيف والقصور الكبدي/الكلوي/القلبي."},{"id":"q233","t":"pharma","l":"pain","q":"Dafalgan و Perfalgan اسمن العلمي:","o":["Kétoprofène","Paracétamol","Tramadol"],"a":1,"x":"Dafalgan / Perfalgan = Paracétamol. Profénid = Kétoprofène. Tramal = Tramadol."},{"id":"q234","t":"pharma","l":"pain","q":"Tramal (Tramadol) مسكّن أفيوني (Opioïde): شو منراقب؟","o":["Surveillance de l’audition (مراقبة السمع)","Surveillance de la glycémie (سكر الدم)","الكمية (الجرعة) لأنو في خطر Dépendance (إدمان)"],"a":2,"x":"Tramal = Analgésique opioïde للآلام الشديدة. منراقب الجرعة بسبب خطر الإدمان. من أعراضو: نعاس، إمساك، غثيان، دوار."},{"id":"q235","t":"pharma","l":"pain","q":"Profénid (Kétoprofène) و Olfen (Diclofenac) من عائلة:","o":["AINS (مضادات الالتهاب غير الستيرويدية)","Corticoïde (كورتيزون) — stéroïdien","Opioïde (أفيوني) — morphinique"],"a":0,"x":"Profénid و Olfen = AINS: منراقب النزيف الهضمي ووظيفة الكلى، وممنوعين بالقرحة والحمل."},{"id":"q236","t":"pharma","l":"pain","q":"مع Perfalgan (Paracétamol)، شو منراقب؟","o":["Surveillance de pouls (النبض) بس","La fonction hépatique (وظائف الكبد)","Signes de dépendance (علامات الإدمان)"],"a":1,"x":"Perfalgan: مراقبة وظائف الكبد + اختبار حساسية. من أعراضو Toxicité hépatique، وممنوع بالقصور الكبدي الشديد."},{"id":"q237","t":"pharma","l":"cort","q":"Decadron اسمو العلمي:","o":["Méthyl-prednisolone","Budésonide","Dexaméthasone"],"a":2,"x":"Decadron = Dexaméthasone. Solumédrol = Méthyl-prednisolone. Pulmicort = Budésonide."},{"id":"q238","t":"pharma","l":"cort","q":"مريض عم ياخد Solumédrol أو Decadron: شو منراقب؟","o":["الوزن، والـ Na⁺ والسكر بالدم (glycémie)","Surveillance de l’audition (السمع)","Signes de dépendance (علامات الإدمان)"],"a":0,"x":"الكورتيزون: Surveillance du poids + Na⁺ + glycémie (ومع Solumédrol كمان الضغط)."},{"id":"q239","t":"pharma","l":"cort","q":"من الأعراض الجانبية للكورتيزون (Solumédrol / Decadron):","o":["Hypoglycémie (هبوط السكر) و Hypotension (هبوط الضغط)","Hyperglycémie (ارتفاع السكر)، Œdème (وذمة)، و HTA (ارتفاع الضغط)","Candidose buccale (فطريات الفم) بس"],"a":1,"x":"الكورتيزون: ارتفاع السكر، وذمة، ارتفاع الضغط، زيادة الوزن، اضطراب الكهارل (Solumédrol: نقص البوتاسيوم)."},{"id":"q240","t":"pharma","l":"cort","q":"Solumédrol ممنوع (contre-indiqué) بـ:","o":["Asthme (الربو) وأمراض الحساسية الجلدية","Œdème du cerveau (وذمة دماغية) والتهاب المفاصل الروماتيزمي","Maladie virale en évolution (hépatite، zona، herpès) أو عدوى/فطريات مش مسيطر عليها"],"a":2,"x":"الربو والوذمة الدماغية من استعمالات Solumédrol. ممنوع: مرض فيروسي نشط، عدوى أو فطريات مش مسيطر عليها، استعداد للنزيف."},{"id":"q241","t":"pharma","l":"cort","q":"مع Solumédrol، أي حمية منوصّي فيها؟","o":["Régime pauvre en sucre et en sel (قليلة السكر والملح)","Régime riche en sel (حمية غنية بالملح)","Régime riche en sucre (حمية غنية بالسكر)"],"a":0,"x":"لأنو بيرفع السكر وبيحبس المي والملح: Régime pauvre en sucre et en sel + مراقبة الوزن والضغط."},{"id":"q242","t":"quality","l":"q2","q":"العصف الذهني (Brainstorming) هو:","o":["مخطط بشكل سمكة لتحديد المسببات","رسم بياني منطلق من نظرية 20% من الأسباب ← 80% من النتائج","اجتماع خلّاق منظّم بينطرح فيه الأفكار لحل المشكلات المعقدة"],"a":2,"x":"Brainstorming = اجتماع خلّاق منظّم لطرح الأفكار. السمكة = Ishikawa. 20/80 = Pareto."},{"id":"q243","t":"pharma","l":"cardio","q":"مريض عم ياخد Cordarone (Antiarythmique): شو منراقب؟","o":["La fonction de thyroïde (الغدة الدرقية) و ECG (تخطيط القلب)","Surveillance de l’audition (السمع) والتوازن","Signes de dépendance (علامات الإدمان) والنوم"],"a":0,"x":"Cordarone بينظّم إيقاع القلب (Régularise le rythme cardiaque): مراقبة وظيفة الغدة الدرقية + ECG."},{"id":"q244","t":"pharma","l":"coag","q":"مع Actilyse / Streptase (Thrombolytique)، شو منراقب؟","o":["Surveillance de la glycémie (السكر) بس، كل ساعة","Surveillance ECG (تخطيط القلب) + signes d’hémorragies (علامات النزيف)","Soin de bouche (العناية بالفم) وفطريات الفم"],"a":1,"x":"Thrombolytique = بيحلّ الجلطة (Lyse de caillot): مراقبة ECG وعلامات النزيف."}];
